import React from "react"
import { SurfaceCardNested, type SurfaceCardNestedSection } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { AsyncContent, type AsyncContentErrorProps } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"

/**
 * `ChangelogList` ΓÇö the dashboard right-rail "What's new" list: dated rows with
 * an optional category, a title that links to the entry when it has a
 * destination, and an optional one-line body. `SurfaceCardNested` owns the
 * card-in-card frame; `AsyncContent` owns the error/loading/empty/content
 * switch. `isLoading` and `error` each swap the whole region; an empty
 * `entries` array renders nothing.
 */

/** Category of a changelog entry ΓÇö mirrors `ChangelogCategory` (backend-sourced enum). */
export type ChangelogCategory = "feature" | "fix" | "announcement"

/** One changelog row ΓÇö plain DATA; the block builds the meta line, link target and body styling. */
export interface ChangelogListEntry {
    /** Stable id ΓÇö the React key. */
    id: string
    /** Headline. */
    title: string
    /** Short body under the title. Row has no third line when absent. */
    body?: string | null
    /** Drives the meta line's trailing label via {@link CATEGORY_LABEL}. Row has no category text when absent. */
    category?: ChangelogCategory | null
    /** ISO publish date ΓÇö the block formats it (`vi-VN`). */
    publishedAt: string
    /** "Read more" destination. Present ΓåÆ the whole row becomes a link (see file header). */
    linkUrl?: string | null
}

/** Props for {@link ChangelogList}. */
export interface ChangelogListProps {
    /** The recent changelog entries, newest first. REQUIRED ΓÇö see file header ┬ºR0. */
    entries: Array<ChangelogListEntry>
    /** `true` ΓåÆ the list's own fetch is in flight; own LEAF (see file header). */
    isLoading: boolean
    /** Truthy ΓåÆ the list falls to its error message; own LEAF (beats loading/empty). */
    error?: unknown
    /** Fired when the reader presses "Retry" on the error branch. Omit to render the error with no action. */
    onRetry?: () => void
    /** Extra classes on the root. */
    className?: string
}

/** The block's own section label ΓÇö matches `dashboard.changelog` in `vi.json`. */
const TITLE = "What's new"

/** category ΓåÆ meta-line label ΓÇö the block's own vocabulary (┬º14d.1), never handed in by a caller. */
const CATEGORY_LABEL: Record<ChangelogCategory, string> = {
    feature: "Feature",
    fix: "Fix",
    announcement: "Announcement",
}

const ERROR_TITLE = "Couldn't load the changelog. Please try again."
const RETRY_LABEL = "Retry"

/** How many placeholder rows mirror the list while `entries` hasn't landed yet. */
const SKELETON_ROW_COUNT = 4

/** Formats an ISO date the same way across every row ΓÇö the block's one date rule. */
const formatDate = (iso: string) => new Date(iso).toLocaleDateString("vi-VN")

/** One row's meta line: the formatted date, plus the category label when present. */
const metaLine = (entry: ChangelogListEntry): string => {
    const category = entry.category ? CATEGORY_LABEL[entry.category] : null
    return category ? `${formatDate(entry.publishedAt)} ┬╖ ${category}` : formatDate(entry.publishedAt)
}

/** Placeholder rows for the loading mirror ΓÇö no data, no press target (┬º12c). */
const skeletonItems = (): Array<SurfaceCardNestedSection> =>
    Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        eyebrow: "x",
        title: "x",
        content: () => <Typography size="sm" color="muted" isSkeleton text="x" />,
    }))

/** One real row: meta line, title (linked when `linkUrl` is set), optional body. */
const entryItem = (entry: ChangelogListEntry): SurfaceCardNestedSection => ({
    key: entry.id,
    eyebrow: metaLine(entry),
    title: entry.title,
    content: entry.body ? () => <Typography size="sm" color="muted" text={entry.body} /> : undefined,
    href: entry.linkUrl ?? undefined,
})

/**
 * The dashboard "What's new" rail. See the file header for the full contract,
 * the leaf boundary reasoning and the judgement calls (meta-line text instead
 * of a chip, whole-row link, no outer label wrapper, plain-text body).
 *
 * @param props - {@link ChangelogListProps}
 */
const ChangelogList = ({
    entries,
    isLoading,
    error,
    onRetry,
    className,
}: ChangelogListProps) => {
    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel: onRetry ? RETRY_LABEL : undefined,

    }

    return (
        <div className={className}>
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <SurfaceCardNested
                        title={TITLE}
                        items={skeletonItems()}
                        isSkeleton
                    />
                )}
                isEmpty={entries.length === 0}
                error={error}
                errorContent={errorContent}
                content={() => (
                    <SurfaceCardNested
                        title={TITLE}
                        items={entries.map(entryItem)}
                    />
                )}
            />
        </div>
    )
}

export { ChangelogList }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { UserCell } from "@sb-components/composites/lists/UserCell/UserCell"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK ΓÇö `WeeklyChallengeCard`: "Weekly Challenge" ΓÇö the featured challenge of
 * the week. See the component's own file header for the full contract; this
 * file only adds the states.
 *
 *  LEAF by STRUCTURE (┬º14d.2): whether the viewer already passed, already
 * claimed, or the leaderboard is short, are all DATA conditions of the same
 * status row/list ΓÇö never a different shape this block draws ΓÇö so this block
 * has exactly ONE leaf ("Content"), the same shape `LeaderboardBoard`'s single
 * `Board` leaf uses.
 */

/** One leaderboard row: a finisher who already passed this week's challenge. */
export interface WeeklyChallengeLeaderboardEntry {
    /** Stable React key ΓÇö the finisher's username. */
    key: string
    /** Account username; drives the avatar fallback (same contract as {@link UserCell}). */
    username: string
    /** Uploaded avatar URL, or `null`/omitted ΓÇö a generated default is shown instead. */
    avatar?: string | null
    /** Already-worded "x ago" label (e.g. "5 minutes ago"). */
    passedAtLabel: string
}

/** The currently featured weekly-challenge event. */
export interface WeeklyChallengeData {
    /** Title of the featured challenge. */
    title: string
    /** Fired from the title AND the "Try it now" prompt ΓÇö the caller already resolved the route. Omit when not routable. */
    onOpenChallenge?: () => void
    /** Already-worded countdown to the event's close (e.g. "2 days 6 hours left"). Omit while unknown. */
    endsInLabel?: string
    /** Whether the viewer has already passed the challenge this week. */
    viewerPassed: boolean
    /** Whether the viewer already claimed the reward this week. Ignored unless `viewerPassed`. */
    claimed: boolean
    /** Coin reward for claiming; `null` when the viewer hasn't passed yet. */
    coinReward: number | null
    /** `true` ΓåÆ the claim mutation is in flight ΓÇö disables + spins the claim button. */
    isClaiming?: boolean
    /** Fired when the viewer presses the claim button. Required whenever `viewerPassed && !claimed`. */
    onClaim?: () => void
    /** Total number of users who have passed so far. */
    passedCount: number
    /** Top finishers (already capped by the caller), newest first. */
    leaderboard: Array<WeeklyChallengeLeaderboardEntry>
}

/** Props for {@link WeeklyChallengeCard}. */
export interface WeeklyChallengeCardProps {
    /** True while the first load is running ΓÇö {@link AsyncContent}'s loading branch. */
    isLoading: boolean
    /** True (once loaded) ΓåÆ no challenge event is currently active. */
    isEmpty: boolean
    /** Truthy ΓåÆ the snapshot failed to load. Pass SWR's `error`. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry: () => void
    /** The featured challenge. Required once loaded and non-empty. */
    data?: WeeklyChallengeData
    /** `true` ΓåÆ every atom this block owns switches to its own shimmer (data already loaded). */
    isSkeleton?: boolean
}

/** The title: a routable link when `onOpenChallenge` is set, plain bold text otherwise. */
const titleText = (data: WeeklyChallengeData, isSkeleton: boolean) =>
    data.onOpenChallenge ? (
        <Typography
            size="sm"
            isLink
            isSkeleton={isSkeleton}
            onPress={data.onOpenChallenge}
            text={data.title}

        />
    ) : (
        <Typography
            size="sm"
            weight="bold"
            isSkeleton={isSkeleton}
            text={data.title}

        />
    )

/** Right side of the status row: claimed chip, a pending claim button, or a "try now" prompt. */
const statusSlot = (data: WeeklyChallengeData, isSkeleton: boolean) => {
    if (isSkeleton) {
        return <Chip isSkeleton />
    }
    if (!data.viewerPassed) {
        return data.onOpenChallenge ? (
            <Typography
                size="xs"
                isLink
                onPress={data.onOpenChallenge}
                text="Try it now"

            />
        ) : null
    }
    if (data.claimed) {
        return (
            <Chip tone="success" text="Completed" />
        )
    }
    return (
        <Button
            variant="primary"
            size="sm"
            isPending={data.isClaiming}
            onPress={data.onClaim}
            label={`Claim ${data.coinReward ?? 0} coins`}
        />
    )
}

/** Builds one finisher's free-form `SurfaceCardList` content: the unchanged `UserCell`. */
const finisherItem = (entry: WeeklyChallengeLeaderboardEntry, isSkeleton: boolean): SurfaceCardListItem => ({
    key: entry.key,
    content: () => (
        <div>
            <UserCell
                username={entry.username}
                avatar={entry.avatar}
                trailing={({ isSkeleton: slotSkeleton }: SkeletonProps) => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={slotSkeleton}
                        text={slotSkeleton ? undefined : entry.passedAtLabel}

                    />
                )}
                isSkeleton={isSkeleton}

            />
        </div>
    ),
})

/** Fixed-shape placeholder rendered while {@link WeeklyChallengeCardProps.isLoading} ΓÇö no real event exists yet. */
const LOADING_DATA: WeeklyChallengeData = {
    title: "",
    viewerPassed: false,
    claimed: false,
    coinReward: null,
    passedCount: 0,
    leaderboard: Array.from({ length: 3 }, (_, index) => ({ key: `loading-${index}`, username: "", passedAtLabel: "" })),
}

/** Props for the internal {@link Content} tree ΓÇö reused for both the real render and the loading skeleton. */
interface ContentProps {
    data: WeeklyChallengeData
    isSkeleton: boolean
}

const Content = ({ data, isSkeleton }: ContentProps) => {
    const statusRow = (
        <StackH gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            justify="between" align="center" items={[
                () => (data.endsInLabel != null || isSkeleton ? (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : data.endsInLabel}

                    />
                ) : <span />),
                () => statusSlot(data, isSkeleton),
            ]} />
    )

    return (
        <StackV gap={4} items={[
            () => titleText(data, isSkeleton),
            () => statusRow,
            () => (
                <Typography
                    size="xs"
                    color="muted"
                    isSkeleton={isSkeleton}
                    text={isSkeleton ? undefined : `${data.passedCount} people have passed`}

                />
            ),
            ...(data.leaderboard.length > 0 ? [() => (
                <div>
                    <SurfaceCardList
                        variant="nested"
                        items={data.leaderboard.map((entry) => finisherItem(entry, isSkeleton))}

                    />
                </div>
            )] : []),
        ]} />
    )
}

/**
 * "Weekly Challenge" ΓÇö the featured weekly-challenge card. See the file header
 * for the full contract.
 *
 * @param props - {@link WeeklyChallengeCardProps}
 */
const WeeklyChallengeCard = ({
    isLoading,
    isEmpty,
    error,
    onRetry,
    data,
    isSkeleton = false,
}: WeeklyChallengeCardProps) => (
    <SurfaceCard
        identity={{ tier: "block", component: "WeeklyChallengeCard" }}
        label="Weekly Challenge"


        body={() => (
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => <Content data={LOADING_DATA} isSkeleton />}
                isEmpty={isEmpty}
                emptyContent={{
                    title: "No challenge is currently active",
                    description: "Check back next week for a new challenge.",
                }}
                error={error}
                errorContent={{
                    title: "Couldn't load the weekly challenge",
                    description: "Try again for the latest info.",
                    onRetry,
                    retryLabel: "Retry",
                }}
                content={() => (data ? (
                    <Content data={data} isSkeleton={isSkeleton} />
                ) : null)}
            />
        )}
    />
)

export { WeeklyChallengeCard }

import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import {
    BookOpenIcon,
    CardsIcon,
    CodeIcon,
    FlagIcon,
    FlameIcon,
    PuzzlePieceIcon,
    type Icon as PhosphorIcon,
} from "@phosphor-icons/react"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { StatGridCard, type StatGridCardItem } from "@sb-components/composites/stats/StatGridCard/StatGridCard"
import { ProgressMeter } from "@sb-components/composites/stats/ProgressMeter/ProgressMeter"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK ΓÇö `WeeklyGoals`: "Weekly Goals" ΓÇö the composite summary + six-metric
 * breakdown. See the component's own file header for the full contract; this
 * file only adds the states.
 *
 *  LEAF by STRUCTURE (┬º14d.2): the six metrics never change the SHAPE of the
 * tree, only the numbers inside it, so this block has exactly ONE leaf
 * ("Content") ΓÇö loading / error / content are states of that one leaf, the
 * same shape `ChallengeScoreCard`'s single leaf uses. No `isEmpty` state:
 * `items` is always the fixed six-metric set (see the component file header).
 */

/** The six weekly metrics this block always renders, in display order (mirrors backend `KpiKey`). */
export type WeeklyGoalKey = "lessons" | "studyDays" | "challenges" | "coding" | "flashcards" | "milestones"

/** One weekly-goal metric: current-week value vs the effective target, plus its coin reward. */
export interface WeeklyGoalItem {
    /** Which metric this row is. */
    key: WeeklyGoalKey
    /** Already-localized metric name (e.g. "Lessons") ΓÇö screen copy, not owned by this block. */
    label: string
    /** The current-week value. */
    current: number
    /** The learner's custom weekly target; `null` when none set (the block falls back to a sensible default). */
    target: number | null
    /** Coin reward for claiming this metric this week; `null` when no target is set server-side. */
    coinReward: number | null
    /** `true` ΓåÆ this metric's reward can be claimed right now (met + not yet claimed). */
    canClaim: boolean
}

/** Server-computed composite score across every metric ΓÇö read straight, never recomputed. */
export interface WeeklyGoalsComposite {
    /** Average completion across the six metrics, 0ΓÇô100. */
    percent: number
    /** Number of metrics already met (current >= effective target). */
    completed: number
    /** Always 6 ΓÇö the fixed metric count. */
    total: number
}

/** The viewer's weekly-goals snapshot (real shape of `myKpis`). */
export interface WeeklyGoalsData {
    /** All six metrics, in display order. */
    items: Array<WeeklyGoalItem>
    /** Server-computed composite score across every metric ΓÇö read straight, never recomputed. */
    composite: WeeklyGoalsComposite
    /** Already-worded countdown to the weekly reset (e.g. "3 days 12 hours left"). Omit while unknown. */
    resetInLabel?: string
}

/** Props for {@link WeeklyGoals}. */
export interface WeeklyGoalsProps {
    /** True while the first load is running ΓÇö {@link AsyncContent}'s loading branch. */
    isLoading: boolean
    /** Truthy ΓåÆ the snapshot failed to load. Pass SWR's `error`. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry: () => void
    /** The viewer's weekly-goals snapshot. Required once loaded (no error). */
    data?: WeeklyGoalsData
    /** Sensible default target per metric, used when a metric has no custom `target` set yet. */
    defaultTargets: Record<WeeklyGoalKey, number>
    /** `true` ΓåÆ every atom this block owns switches to its own shimmer (data already loaded). */
    isSkeleton?: boolean
}

/** Phosphor icon per metric key ΓÇö a pure display constant, decoupled from any editor's own map. */
const KPI_ICON: Record<WeeklyGoalKey, PhosphorIcon> = {
    lessons: BookOpenIcon,
    studyDays: FlameIcon,
    challenges: PuzzlePieceIcon,
    coding: CodeIcon,
    flashcards: CardsIcon,
    milestones: FlagIcon,
}

/** One metric cell's content: icon + label + ratio row, then the meter, then an optional coin hint. */
const goalCellContent = (
    item: WeeklyGoalItem,
    defaultTargets: Record<WeeklyGoalKey, number>,
    isSkeleton: boolean,
) => {
    const Icon = KPI_ICON[item.key]
    const effectiveTarget = item.target ?? defaultTargets[item.key]

    const iconLabel = (
        <StackH gap={2} isSkeleton={isSkeleton} items={[
            () => (isSkeleton ? (
                <HeroSkeleton
                    className="size-5 shrink-0 rounded-full"

                />
            ) : (
                <Icon aria-hidden focusable="false" className="size-5 shrink-0 text-muted" />
            )),
            () => (
                <Typography
                    size="sm"
                    isSkeleton={isSkeleton}
                    text={item.label}

                />
            ),
        ]} />
    )

    const labelRow = (
        <StackH gap={3} principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            justify="between" isSkeleton={isSkeleton} items={[
                () => iconLabel,
                () => (
                    <Typography
                        size="xs"
                        color="muted"
                        tabularNums
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : `${item.current}/${effectiveTarget}`}

                    />
                ),
            ]} />
    )

    return (
        <StackV gap={3} isSkeleton={isSkeleton} items={[
            () => labelRow,
            () => (
                <ProgressMeter
                    value={item.current}
                    max={effectiveTarget > 0 ? effectiveTarget : 1}
                    isSkeleton={isSkeleton}
                />
            ),
            ...(!isSkeleton && item.coinReward != null ? [() => (
                <Typography
                    size="xs"
                    color={item.canClaim ? "accent" : "muted"}
                    isSkeleton={isSkeleton}
                    text={`+${item.coinReward} coins when met`}

                />
            )] : []),
        ]} />
    )
}

/** Fixed-shape placeholder rendered while {@link WeeklyGoalsProps.isLoading} ΓÇö six empty cells, no real data yet. */
const loadingItems = (defaultTargets: Record<WeeklyGoalKey, number>): Array<WeeklyGoalItem> =>
    (Object.keys(defaultTargets) as Array<WeeklyGoalKey>).map((key) => ({
        key,
        label: "",
        current: 0,
        target: null,
        coinReward: null,
        canClaim: false,
    }))

/** Props for the internal {@link Content} tree ΓÇö reused for both the real render and the loading skeleton. */
interface ContentProps {
    items: Array<WeeklyGoalItem>
    composite: WeeklyGoalsComposite
    resetInLabel?: string
    defaultTargets: Record<WeeklyGoalKey, number>
    isSkeleton: boolean
}

const Content = ({ items, composite, resetInLabel, defaultTargets, isSkeleton }: ContentProps) => {
    const summary = isSkeleton
        ? undefined
        : `${composite.percent}% complete (${composite.completed}/${composite.total} goals)${resetInLabel != null ? ` ┬╖ ${resetInLabel}` : ""}`
    const gridItems: Array<StatGridCardItem> = items.map((item) => ({
        key: item.key,
        content: () => goalCellContent(item, defaultTargets, isSkeleton),
    }))
    return (
        <StackV gap={4} isSkeleton={isSkeleton} items={[
            () => (
                <Typography
                    size="sm"
                    weight="medium"
                    isSkeleton={isSkeleton}
                    text={summary}

                />
            ),
            () => (
                <div>
                    <StatGridCard items={gridItems} />
                </div>
            ),
        ]} />
    )
}

/**
 * "Weekly Goals" ΓÇö the weekly-goal summary + six-metric breakdown. See the
 * file header for the full contract.
 *
 * @param props - {@link WeeklyGoalsProps}
 */
const WeeklyGoals = ({
    isLoading,
    error,
    onRetry,
    data,
    defaultTargets,
    isSkeleton = false,
}: WeeklyGoalsProps) => (
    <SurfaceCard
        identity={{ tier: "block", component: "WeeklyGoals" }}
        label="Weekly Goals"


        body={() => (
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <Content
                        items={loadingItems(defaultTargets)}
                        composite={{ percent: 0, completed: 0, total: 6 }}
                        defaultTargets={defaultTargets}
                        isSkeleton

                    />
                )}
                error={error}
                errorContent={{
                    title: "Couldn't load weekly goals",
                    description: "Retry to see the latest progress.",
                    onRetry,
                    retryLabel: "Retry",
                }}
                content={() => (data ? (
                    <Content
                        items={data.items}
                        composite={data.composite}
                        resetInLabel={data.resetInLabel}
                        defaultTargets={defaultTargets}
                        isSkeleton={isSkeleton}

                    />
                ) : null)}
            />
        )}
    />
)

export { WeeklyGoals }

import React from "react"
import type { ComponentType, SVGProps } from "react"
import {
    CalendarBlankIcon,
    GithubLogoIcon,
    GlobeIcon,
    HandshakeIcon,
    LinkedinLogoIcon,
    MapPinIcon,
    PencilSimpleIcon,
    UserCheckIcon,
    UserPlusIcon,
} from "@phosphor-icons/react"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { ProfileRankAvatar } from "./ProfileRankAvatar"
import { ProfileFollowers } from "./ProfileFollowers"
import { ProfileBadges } from "./ProfileBadges"
import { ShareProfileButton } from "./ShareProfileButton"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import type { ButtonVariant } from "@sb-components/atoms/buttons/Button/Button"
import { EnumChip, type EnumChipEntry } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { InlineIconLabel } from "@sb-components/composites/text/InlineIconLabel/InlineIconLabel"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ProfileHero` ΓÇö the identity sidebar for a person's profile page:
 * rank-framed avatar, name/@handle/role, bio, location + work-mode, follower
 * and badge social proof, one primary CTA (hire/follow/edit) + share, and a
 * github/linkedin/website/joined meta list. Composed from `SurfaceCard` around
 * `StackV`/`StackH`/`Cluster` holding `Avatar`/`Typography`/`Chip`/`Button`/
 * `Divider` plus `EnumChip`/`InlineIconLabel`. Two leaves: `Default` (every
 * optional row present; CTA/skeleton/follow-state are content states) and
 * `Minimal` (no rank/role/bio/location/work-mode/badges/social links ΓÇö losing
 * those removes real nodes, earning its own leaf).
 */

/** An icon passed as a COMPONENT (e.g. a Phosphor `*Icon`), rendered at the tile's own scale. Declared locally per atom convention (┬º5.0) rather than importing one library's type. */
type IconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/** How this person works ΓÇö the block owns the label wording (┬º14d.1), the caller only says which one. */
export type ProfileWorkMode = "remote" | "onsite" | "hybrid"

/** External profile links. Each is optional; an absent one simply drops its meta row. */
export interface ProfileSocialLinks {
    /** GitHub profile URL. */
    github?: string
    /** LinkedIn profile URL. */
    linkedin?: string
    /** Personal site/portfolio URL. */
    website?: string
}

/** One achievement/verification badge earned by this person. */
export interface ProfileBadge {
    /** Stable id ΓÇö used as the chip's React key. */
    id: string
    /** Badge label, already worded by the caller's domain (e.g. "Top mentor"). */
    label: string
    /** Optional leading glyph for the badge chip. */
    icon?: IconComponent
}

/** The person this hero profiles ΓÇö plain data, the block builds the sidebar from it. */
export interface ProfileHeroUser {
    /** Stable id (not rendered; kept for parity with other domain-user shapes). */
    id: string
    /** Full display name. */
    fullName: string
    /** Handle WITHOUT the leading `@` ΓÇö the block adds it (┬º14d.1). */
    handle: string
    /** Role/title line under the name. Row disappears when absent. */
    roleTitle?: string
    /** Short bio/about text. Row disappears when absent. */
    bio?: string
    /** Free-text location (e.g. "Hanoi, Vietnam"). Row disappears when absent. */
    location?: string
    /** How this person works. Row disappears when absent. */
    workMode?: ProfileWorkMode
    /** Photo URL. Empty/missing ΓåÆ `Avatar`'s own fallback chain, never a blank frame. */
    avatarUrl?: string
    /** Leaderboard-style standing (1 = top). Absent ΓåÆ no rank frame/caption at all. */
    rank?: number
    /** Total followers. Absent renders as `0` (a real, known count of nothing). */
    followersCount?: number
    /** Achievement badges earned. Empty/absent ΓåÆ the badges row disappears entirely. */
    badges?: ReadonlyArray<ProfileBadge>
    /** ISO date string this person joined. Required ΓÇö every profile has one. */
    joinedAt: string
    /** External links. Absent/all-empty ΓåÆ the social rows of the meta list disappear. */
    social?: ProfileSocialLinks
}

/** Props for {@link ProfileHero}. */
export interface ProfileHeroProps {
    /** The profiled person. */
    user: ProfileHeroUser
    /** `true` ΓåÆ the viewer IS this person: the primary CTA becomes "Edit profile", follow/hire never show. */
    isSelf?: boolean
    /** `true` (and not `isSelf`) ΓåÆ the primary CTA becomes "Hire me" instead of follow. */
    canHire?: boolean
    /** Whether the viewer already follows this person. Ignored when `isSelf`/`canHire`. */
    following?: boolean
    /** `true` ΓåÆ the follow CTA shows its busy state while the toggle is in flight. */
    isFollowPending?: boolean
    /** Fired when the viewer toggles follow (only reachable when neither `isSelf` nor `canHire`). */
    onToggleFollow?: () => void
    /** Fired when the viewer presses "Hire me" (only reachable when `canHire` and not `isSelf`). See file header, judgement call 3. */
    onHire?: () => void
    /** Fired when the profile owner presses "Edit profile" (only reachable when `isSelf`). */
    onEdit?: () => void
    /** Fired when the share action is pressed. */
    onShare?: () => void
    /** `true` ΓåÆ every real part switches to its own shimmer; the profile stops accepting presses. */
    isSkeleton?: boolean
}

interface PrimaryAction {
    label: string
    variant: ButtonVariant
    prefixIcon: IconComponent
    onPress?: () => void
    isPending?: boolean
}

/** Inputs {@link resolvePrimaryAction} needs to pick the one CTA slot. */
interface ResolvePrimaryActionParams {
    isSelf: boolean
    canHire: boolean
    following: boolean
    isFollowPending: boolean
    onEdit?: () => void
    onHire?: () => void
    onToggleFollow?: () => void
}

const resolvePrimaryAction = (params: ResolvePrimaryActionParams): PrimaryAction => {
    const { isSelf, canHire, following, isFollowPending, onEdit, onHire, onToggleFollow } = params
    if (isSelf) {
        return { label: "Edit profile", variant: "secondary", prefixIcon: PencilSimpleIcon, onPress: onEdit }
    }
    if (canHire) {
        return { label: "Hire me", variant: "primary", prefixIcon: HandshakeIcon, onPress: onHire }
    }
    return {
        label: following ? "Following" : "Follow",
        variant: following ? "secondary" : "primary",
        prefixIcon: following ? UserCheckIcon : UserPlusIcon,
        onPress: onToggleFollow,
        isPending: isFollowPending,
    }
}

