import { InputTextarea } from "@/components/atoms/forms"
import React from "react"
import type { ReactNode } from "react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { CommunityCommentRow } from "@/components/blocks/feed/CommunityCommentRow"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"

import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"
import type { QueryCommunityCommentNode } from "@/modules/api/graphql/queries/types/community-comments"

/** How many placeholder rows the co-located skeleton shows while the replies list loads. */
const SKELETON_REPLY_COUNT = 2

/** All display text, already localized by the connected {@link import("./index").CommunityCommentItem}; a story passes i18n keys. */
export interface CommunityCommentItemLabels {
    /** "Reply" toggle under the comment (only when signed in and the comment isn't deleted). */
    replyToggle: string
    /** "View N replies" ΓÇö shown when the reply list is collapsed. Already interpolated with the count. */
    viewReplies: string
    /** "Hide replies" ΓÇö shown when the reply list is open. */
    hideReplies: string
    /** Placeholder + accessible name for the reply textarea. */
    replyPlaceholder: string
    /** Submit button label on the reply box. */
    send: string
    /** Settled with zero replies ΓÇö the replies region's empty title. */
    repliesEmptyTitle: string
    /** Settled with a fetch error ΓÇö the replies region's error title. */
    repliesErrorTitle: string
    /** Retry-button label on the replies region's error state. */
    retry: string
}

/** Props for {@link _CommunityCommentItem} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface CommunityCommentItemProps {
    /** The top-level comment to render (with its reply controls). */
    comment: QueryCommunityCommentNode
    /** Whether the viewer is signed in (gates reply + reactions). */
    authenticated: boolean
    /** React to this top-level comment. Omit to render the reaction bar read-only. */
    onReact?: (type: ReactionType | null) => void

    /** Whether the reply textarea is open. */
    replyOpen: boolean
    /** Toggles {@link CommunityCommentItemProps.replyOpen}. */
    onToggleReplyOpen: () => void
    /** Current (controlled) reply draft. */
    replyBody: string
    /** Fired on every keystroke in the reply textarea. */
    onReplyBodyChange: (value: string) => void
    /** Submits {@link CommunityCommentItemProps.replyBody} as a reply. */
    onSubmitReply: () => void
    /** True while the reply mutation is in flight ΓÇö locks the send button. */
    isSubmittingReply?: boolean

    /** Whether the replies list is expanded. */
    repliesOpen: boolean
    /** Toggles {@link CommunityCommentItemProps.repliesOpen}. */
    onToggleReplies: () => void
    /** First load, nothing in hand ΓåÆ the replies region shimmers in place (co-located). Owned by the connected file. */
    repliesIsSkeleton?: boolean
    /** Settled with zero replies ΓåÆ the replies region's empty message. */
    repliesIsEmpty?: boolean
    /** Truthy ΓåÆ the replies region's error message (beats loading + empty). */
    repliesError?: unknown
    /** Retries the failed replies query. */
    onRetryReplies?: () => void
    /** The loaded replies, already resolved. */
    replies?: Array<QueryCommunityCommentNode>
    /** React to one of the replies. Omit to render every reply's reaction bar read-only. */
    onReactReply?: (replyId: string, type: ReactionType | null) => void

    labels: CommunityCommentItemLabels
}

/**
 * A top-level community comment with its reply affordances: react, reply (one level deep), and an
 * expandable list of its replies ΓÇö the presentational half of
 * {@link import("./index").CommunityCommentItem} (`tiers/split.md`). The replies region renders
 * error ΓåÆ skeleton ΓåÆ empty ΓåÆ content in that fixed order (BLOCK-8); `CommunityCommentRow` (the reply
 * row) takes no `isSkeleton` of its own, so while shimmering the SAME list position swaps in a bare
 * `Skeleton.ListRow` instead of threading a flag through it (`loading-and-skeleton.md` ┬º1's stated
 * exception).
 *
 * @param props - {@link CommunityCommentItemProps}
 */
export const _CommunityCommentItem = ({
    comment,
    authenticated,
    onReact,
    replyOpen,
    onToggleReplyOpen,
    replyBody,
    onReplyBodyChange,
    onSubmitReply,
    isSubmittingReply = false,
    repliesOpen,
    onToggleReplies,
    repliesIsSkeleton = false,
    repliesIsEmpty = false,
    repliesError,
    onRetryReplies,
    replies = [],
    onReactReply,
    labels,
}: CommunityCommentItemProps) => {
    const showReplyToggle = authenticated && !comment.isDeleted
    const showViewReplies = comment.replyCount > 0

    const actions = showReplyToggle || showViewReplies
        ? (
            <StackH gap={4} items={[
                ...(showReplyToggle ? [() => (
                    <Typography size="xs" color="muted" isButton text={labels.replyToggle} onPress={onToggleReplyOpen} />
                )] : []),
                ...(showViewReplies ? [() => (
                    <Typography
                        size="xs"
                        color="accent-soft"
                        isButton
                        text={repliesOpen ? labels.hideReplies : labels.viewReplies}
                        onPress={onToggleReplies}
                    />
                )] : []),
            ]} />
        )
        : undefined

    // error beats a stale skeleton flag; empty only once settled (BLOCK-8)
    let repliesContent: ReactNode = null
    if (repliesOpen) {
        if (repliesError) {
            repliesContent = (
                <AsyncContentError title={labels.repliesErrorTitle} onRetry={onRetryReplies} retryLabel={labels.retry} />
            )
        } else if (!repliesIsSkeleton && repliesIsEmpty) {
            repliesContent = <AsyncContentEmpty title={labels.repliesEmptyTitle} />
        } else {
            // co-located: SAME row list, placeholder rows while shimmering, real rows once resolved.
            // `CommunityCommentRow` has no `isSkeleton` of its own (┬º1's exception) ΓÇö the placeholder
            // swaps in a bare `Skeleton.ListRow` at the same position instead of threading a flag.
            const rows = repliesIsSkeleton
                ? Array.from({ length: SKELETON_REPLY_COUNT }, () => () => (
                    <Skeleton.ListRow withSubtitle withTrailing={false} />
                ))
                : replies.map((reply) => () => (
                    <CommunityCommentRow
                        comment={reply}
                        onReact={authenticated ? (type: ReactionType | null) => onReactReply?.(reply.id, type) : undefined}
                    />
                ))
            repliesContent = <StackV gap={4} items={rows} />
        }
    }

    return (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            identity={{ tier: "block", component: "CommunityCommentItem" }}
            items={[
                () => (
                    <CommunityCommentRow comment={comment} onReact={authenticated ? onReact : undefined} actions={actions} />
                ),
                ...(replyOpen && authenticated ? [() => (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                        nested items={[
                            () => (
                                <InputTextarea
                                    rows={2}
                                    value={replyBody}
                                    onValueChange={onReplyBodyChange}
                                    placeholder={labels.replyPlaceholder}
                                    ariaLabel={labels.replyPlaceholder}
                                    variant="secondary"
                                />
                            ),
                            () => (
                                <Box principle="push-end" className="ml-auto w-fit"
                                    explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                    <Button
                                        variant="primary"
                                        size="sm"
                                        isPending={isSubmittingReply}
                                        isDisabled={!replyBody.trim()}
                                        onPress={onSubmitReply}
                                        label={labels.send}
                                    />
                                </Box>
                            ),
                        ]} />
                )] : []),
                ...(repliesOpen ? [() => (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                        nested body={() => repliesContent}  />
                )] : []),
            ]} />
    )
}

"use client"

import { InputTextarea } from "@/components/atoms/forms"
import React, { useCallback, useState } from "react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Divider } from "@/components/atoms/display/Divider"

import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { CommunityCommentItem } from "@/components/blocks/community/CommunityCommentItem"
import type { QueryCommunityCommentNode } from "@/modules/api/graphql/queries/types/community-comments"

/** How many placeholder rows the co-located skeleton shows while the thread's first load is in flight. */
const SKELETON_ROW_COUNT = 3

/** All display text, already localized by the connected `CommunityCommentThread`; a story passes i18n keys. */
export interface CommunityCommentThreadLabels {
    /** Placeholder + aria-label of the top-level composer. */
    composerPlaceholder: string
    /** Submit button label. */
    send: string
    /** Shown when the thread has settled with zero comments. */
    emptyTitle: string
    /** Shown when the thread has settled with a fetch error, nothing in hand. */
    errorTitle: string
    /** Retry button label, paired with `onRetry`. */
    retry: string
}

/** Props for {@link _CommunityCommentThread} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface CommunityCommentThreadProps {
    /** Post whose comments are shown ΓÇö threaded to each row for its own reply/react calls. */
    postId: string
    /** Whether the viewer is signed in (gates the composer + reactions). */
    authenticated: boolean
    /**
     * First load, nothing in hand ΓåÆ the list shimmers in place (co-located, no parallel
     * tree). Owned by the connected file (loading-and-skeleton.md).
     */
    isSkeleton?: boolean
    /** Settled with zero comments ΓåÆ the empty message. */
    isEmpty?: boolean
    /** Truthy ΓåÆ the error message (beats a stale loading flag). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler, paired with `labels.retry` on the error branch. */
    onRetry?: () => void
    /** Top-level comments to render; ignored while `isSkeleton`. */
    comments?: Array<QueryCommunityCommentNode>
    /** Refresh the thread after a row-level change (reply/react) ΓÇö also bubbles up to the feed. */
    onItemChanged?: () => void
    /** Submit the composer's trimmed body; resolves `true` on success so the composer clears itself. */
    onSubmit: (body: string) => Promise<boolean>
    /** True while the create-comment mutation is in flight. */
    isSubmitting?: boolean
    labels: CommunityCommentThreadLabels
}

/**
 * Expandable comment thread under a community post: lists top-level comments (each with its own
 * reply + nested-replies controls via {@link CommunityCommentItem}), plus a composer for signed-in
 * users. The presentational half of {@link import("./index").CommunityCommentThread} ΓÇö error beats a
 * stale loading flag, empty only once settled, otherwise the ONE tree renders with `isSkeleton`
 * threaded down. `CommunityCommentItem` carries no `isSkeleton` of its own, so the loading branch
 * swaps in `Skeleton.ListRow` placeholders right where the real rows sit (loading-and-skeleton.md).
 * See `tiers/split.md` ΓÇö the connected `index.tsx` owns the fetch, the mutation, and i18n.
 *
 * @param props - {@link CommunityCommentThreadProps}
 */
export const _CommunityCommentThread = ({
    postId,
    authenticated,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    comments = [],
    onItemChanged,
    onSubmit,
    isSubmitting = false,
    labels,
}: CommunityCommentThreadProps) => {
    const [composerValue, setComposerValue] = useState("")

    /** Submit the composer, then clear it only once the connected half confirms success. */
    const onComposerSubmit = useCallback(async () => {
        const trimmed = composerValue.trim()
        if (!trimmed) {
            return
        }
        const ok = await onSubmit(trimmed)
        if (ok) {
            setComposerValue("")
        }
    }, [composerValue, onSubmit])

    // Rows: `CommunityCommentItem` has no `isSkeleton` of its own, so while shimmering a matching
    // count of `Skeleton.ListRow` stands in, right in the same list position (co-located, not a
    // parallel tree) ΓÇö see `missingSkeletonSupport`.
    const rows = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, () => () => (
            <Skeleton.ListRow withSubtitle withTrailing={false} />
        ))
        : comments.map((comment) => () => (
            <CommunityCommentItem
                postId={postId}
                comment={comment}
                authenticated={authenticated}
                onChanged={onItemChanged}
            />
        ))

    // error beats a stale loading flag; empty only once settled (BLOCK-8 / loading-and-skeleton.md).
    let listBody: React.ReactNode
    if (error) {
        listBody = <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    } else if (!isSkeleton && isEmpty) {
        listBody = <AsyncContentEmpty title={labels.emptyTitle} />
    } else {
        listBody = <StackV gap={3} isSkeleton={isSkeleton} items={rows} />
    }

    return (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            identity={{ tier: "block", component: "CommunityCommentThread" }}
            items={[
                () => <Divider />,
                ...(authenticated ? [() => (
                    <StackV gap={2} items={[
                        () => (
                            <InputTextarea
                                variant="secondary"
                                rows={2}
                                value={composerValue}
                                onValueChange={setComposerValue}
                                placeholder={labels.composerPlaceholder}
                                ariaLabel={labels.composerPlaceholder}
                            />
                        ),
                        () => (
                            <Box principle="push-end" className="ml-auto w-fit"
                                explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                <Button
                                    variant="primary"
                                    size="sm"
                                    label={labels.send}
                                    isPending={isSubmitting}
                                    isDisabled={!composerValue.trim()}
                                    onPress={() => void onComposerSubmit()}
                                />
                            </Box>
                        ),
                    ]} />
                )] : []),
                () => listBody,
            ]}
        />
    )
}

"use client"

import React, { useState } from "react"
import { CommunityCommentThread } from "@/components/blocks/community/CommunityCommentThread"
import { CommunityPostCard } from "@/components/blocks/feed/CommunityPostCard"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"
import type { QueryCommunityFeedItemData } from "@/modules/api/graphql/queries/types/community-feed"

/** Props for the {@link CommunityPost} feature. */
export interface CommunityPostProps {
    /** The post to render. */
    post: QueryCommunityFeedItemData
    /** Whether the viewer is signed in (gates reactions + the comment composer). */
    authenticated: boolean
    /** React handler for the post; omit to render the reaction bar read-only. */
    onReact?: (postId: string, type: ReactionType | null) => void
    /** Called when the thread changes (new comment) so the feed can refresh. */
    onChanged?: () => void
}

/**
 * A single feed post plus its expandable comment thread. Owns the per-post
 * "comments open" toggle so the thread only mounts (and fetches) when opened.
 *
 * @param props - {@link CommunityPostProps}
 */
export const CommunityPost = ({
    post,
    authenticated,
    onReact,
    onChanged,
}: CommunityPostProps) => {
    const [commentsOpen, setCommentsOpen] = useState(false)

    return (
        <CommunityPostCard
            post={post}
            onReact={onReact}
            onToggleComments={() => setCommentsOpen((previous) => !previous)}
        >
            {commentsOpen ? (
                <CommunityCommentThread
                    postId={post.id}
                    authenticated={authenticated}
                    onChanged={onChanged}
                />
            ) : null}
        </CommunityPostCard>
    )
}

"use client"

import React, { useEffect, useState } from "react"
import { Button, TextArea, TextField } from "@heroui/react"
import { useTranslations } from "next-intl"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"

/** Props for {@link CommentComposer}. */
export interface CommentComposerProps {
    /** Called with the trimmed body when the user submits a non-empty comment. */
    onSubmit: (body: string) => void
    /** Placeholder text for the textarea. */
    placeholder?: string
    /** Label for the submit button (defaults to a generic "post" copy). */
    submitLabel?: string
    /** Optional cancel handler (renders a cancel button when provided, e.g. for replies/edits). */
    onCancel?: () => void
    /** Initial textarea value (e.g. when editing an existing comment). */
    initialValue?: string
    /** Disables submit while a mutation is in flight. */
    busy?: boolean
    /**
     * When set, the composer is avatar-led: a leading {@link UserAvatar} sits beside the
     * field, and (with `collapsible`) the collapsed pill shows it too.
     */
    currentUser?: { username: string, avatar?: string } | null
    /**
     * Start collapsed as a slim "write a comment" pill (avatar + placeholder) and expand
     * to the full textarea on click ΓÇö the top-level composer pattern. Reply/edit composers
     * omit this and render expanded.
     */
    collapsible?: boolean
}

/**
 * A textarea + submit control used for new comments, replies, and edits.
 *
 * For the top-level composer pass `collapsible` + `currentUser`: it renders as a slim
 * avatar + placeholder pill and expands to the textarea on focus (in the style of YouTube / GitHub),
 * so an empty grey box never dominates the discussion zone.
 *
 * Presentational: owns only the draft text + expand state; submit/cancel are delegated.
 * @param props - {@link CommentComposerProps}
 */
export const CommentComposer = ({
    onSubmit: onSubmitAction,
    placeholder,
    submitLabel,
    onCancel: onCancelAction,
    initialValue,
    busy,
    currentUser,
    collapsible,
}: CommentComposerProps) => {
    const t = useTranslations()
    // draft body kept local until submit
    const [body, setBody] = useState(initialValue ?? "")
    // collapsible composers start closed; everything else is always open
    const [expanded, setExpanded] = useState(!collapsible)
    // sync when the parent passes a new initialValue (e.g. editing a different comment)
    useEffect(() => {
        setBody(initialValue ?? "")
    }, [initialValue])
    const trimmed = body.trim()
    const resolvedPlaceholder = placeholder ?? t("discussion.placeholder")

    // submit only non-empty drafts, then clear (and re-collapse a collapsible composer)
    const onSubmit = () => {
        if (!trimmed) {
            return
        }
        onSubmitAction(trimmed)
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
    }

    const onCancel = () => {
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
        onCancelAction?.()
    }

    // collapsed pill: avatar + placeholder, the whole row opens the composer
    if (collapsible && !expanded) {
        return (
            <button
                type="button"
                onClick={() => setExpanded(true)}
                className="flex w-full items-center gap-3 text-left"
            >
                {currentUser ? (
                    <UserAvatar
                        size="sm"
                        username={currentUser.username}
                        avatar={currentUser.avatar}
                        className="shrink-0"
                    />
                ) : null}
                <span className="flex-1 cursor-pointer rounded-xl border border-default bg-surface px-4 py-2 text-sm text-muted transition-colors hover:bg-default">
                    {resolvedPlaceholder}
                </span>
            </button>
        )
    }

    const form = (
        <div className="flex min-w-0 flex-1 flex-col gap-2">
            <TextField variant="primary" className="w-full">
                <TextArea
                    rows={3}
                    value={body}
                    onChange={(event) => setBody(event.target.value)}
                    placeholder={resolvedPlaceholder}
                    className="resize-none"
                    autoFocus={collapsible}
                />
            </TextField>
            <div className="flex items-center justify-start gap-2">
                <Button
                    size="sm"
                    variant="primary"
                    onPress={onSubmit}
                    // spinner + auto-disable while the mutation is in flight (blocks double-submit)
                    isPending={Boolean(busy)}
                    isDisabled={!trimmed}
                >
                    {submitLabel ?? t("discussion.post")}
                </Button>
                {onCancelAction || collapsible ? (
                    <Button size="sm" variant="tertiary" onPress={onCancel} isDisabled={busy}>
                        {t("common.cancel")}
                    </Button>
                ) : null}
            </div>
        </div>
    )

    // avatar-led when a viewer is known, else just the field (reply/edit keep old layout)
    return (
        <div className="flex w-full gap-3">
            {currentUser ? (
                <UserAvatar
                    size="sm"
                    username={currentUser.username}
                    avatar={currentUser.avatar}
                    className="shrink-0"
                />
            ) : null}
            {form}
        </div>
    )
}

"use client"

import React, { useState } from "react"
import { Link, cn } from "@heroui/react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { pathConfig } from "@/resources/path"
import { EntityLink } from "@/components/blocks/feed/EntityLink"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { ReactionBar } from "./ReactionBar"
import { CommentComposer } from "./CommentComposer"
import { ReactionType, type CommentNode } from "@/modules/api/graphql/queries/types/discussion"
/** Callbacks shared down the comment tree. */
export interface CommentItemCallbacks {
    /** Post a reply under `parentId`. */
    onReply: (parentId: string, body: string) => void
    /** Edit a comment body (author only). */
    onEdit: (commentId: string, body: string) => void
    /** Soft-delete a comment (author only). */
    onDelete: (commentId: string) => void
    /** React to a comment (null removes the reaction). */
    onReactComment: (commentId: string, type: ReactionType | null) => void
    /** Lazily load the replies of `parentId`. */
    onLoadReplies: (parentId: string) => void
}

/** Props for {@link CommentItem}. */
export interface CommentItemProps extends CommentItemCallbacks {
    /** The comment to render. */
    comment: CommentNode
    /** Current viewer id (drives owner-only actions); null when unknown. */
    currentUserId: string | null
    /** Nesting depth (controls visual indentation). */
    depth: number
    /** Replies keyed by parent comment id (lazily populated by the container). */
    repliesByParent: Record<string, Array<CommentNode>>
}

/**
 * A single threaded comment with author, reactions, owner actions, reply box, and its
 * recursively-rendered replies. Visual indentation is capped so deep threads stay readable.
 *
 * Presentational: owns only transient UI state (editing/replying/expanded); persistence is
 * delegated via the {@link CommentItemCallbacks}.
 * @param props - {@link CommentItemProps}
 */
export const CommentItem = ({
    comment,
    currentUserId,
    depth,
    repliesByParent,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies}: CommentItemProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // transient per-comment UI state
    const [replying, setReplying] = useState(false)
    const [editing, setEditing] = useState(false)
    const [expanded, setExpanded] = useState(false)

    const isOwner = currentUserId !== null && currentUserId === comment.author.id
    const replies = repliesByParent[comment.id] ?? []

    // expand/collapse the reply subtree, loading it on first expand
    const toggleReplies = () => {
        const next = !expanded
        setExpanded(next)
        if (next) {
            onLoadReplies(comment.id)
        }
    }

    return (
        <div
            className={cn("flex flex-col gap-2",
                // indent nested replies with a guide border, capped after a few levels
                depth > 0 ? "border-l border-default pl-3 @app-sm:pl-4" : undefined)}
        >
            <div className="flex gap-3">
                <UserAvatar
                    size="sm"
                    username={comment.author.username}
                    avatar={comment.author.avatar}
                    className="mt-0 shrink-0"
                />
                <div className="flex min-w-0 flex-1 flex-col gap-2">
                    {/* author + founder badge + timestamp header */}
                    <div className="flex flex-wrap items-center gap-2">
                        <EntityLink
                            label={comment.author.username}
                            onPress={() => router.push(
                                pathConfig().locale(locale).profile(comment.author.username).build(),
                            )}
                            className="text-sm"
                        />
                        {comment.isFounderAuthor ? (
                            <SealCheckIcon
                                weight="fill"
                                aria-label={t("discussion.founderBadge")}
                                className="size-3.5 shrink-0 text-accent-soft-foreground"
                            />
                        ) : null}
                        <span className="text-xs text-muted">
                            {getTimeAgoLabel(getTimeAgoMessage(comment.createdAt), t)}
                        </span>
                        {comment.editedAt ? (
                            <span className="text-xs text-muted">{t("discussion.edited")}</span>
                        ) : null}
                    </div>

                    {/* body, edit form, or deleted placeholder */}
                    {comment.isDeleted ? (
                        <div className="text-sm italic text-muted">{t("discussion.deletedPlaceholder")}</div>
                    ) : editing ? (
                        <CommentComposer
                            initialValue={comment.body}
                            submitLabel={t("common.save")}
                            onCancel={() => setEditing(false)}
                            onSubmit={(body) => {
                                onEdit(comment.id, body)
                                setEditing(false)
                            }}
                        />
                    ) : (
                        <div className="whitespace-pre-wrap text-sm leading-relaxed text-foreground">
                            {comment.body}
                        </div>
                    )}

                    {/* action row: reactions + reply + owner edit/delete */}
                    {!comment.isDeleted && !editing ? (
                        <div className="flex flex-wrap items-center gap-3">
                            <ReactionBar
                                summary={comment.reactions}
                                onReact={(type) => onReactComment(comment.id, type)}
                            />
                            <Link
                                className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                onPress={() => setReplying((prev) => !prev)}
                            >
                                {t("discussion.reply")}
                            </Link>
                            {isOwner ? (
                                <>
                                    <Link
                                        className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                        onPress={() => setEditing(true)}
                                    >
                                        {t("common.edit")}
                                    </Link>
                                    <Link
                                        className="cursor-pointer text-xs font-medium text-muted hover:text-danger-soft-foreground"
                                        onPress={() => onDelete(comment.id)}
                                    >
                                        {t("common.delete")}
                                    </Link>
                                </>
                            ) : null}
                        </div>
                    ) : null}

                    {/* reply composer */}
                    {replying ? (
                        <CommentComposer
                            placeholder={t("discussion.replyPlaceholder")}
                            submitLabel={t("discussion.reply")}
                            onCancel={() => setReplying(false)}
                            onSubmit={(body) => {
                                onReply(comment.id, body)
                                setReplying(false)
                                // surface the new reply immediately by expanding the subtree
                                setExpanded(true)
                                onLoadReplies(comment.id)
                            }}
                        />
                    ) : null}

                    {/* replies toggle + recursive subtree */}
                    {comment.replyCount > 0 ? (
                        <Link
                            className="cursor-pointer self-start text-xs font-medium text-accent-soft-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)]"
                            onPress={toggleReplies}
                        >
                            {expanded
                                ? t("discussion.hideReplies")
                                : t("discussion.viewReplies", { count: comment.replyCount })}
                        </Link>
                    ) : null}

                    {expanded && replies.length > 0 ? (
                        <div className="mt-1 flex flex-col gap-3">
                            {replies.map((reply) => (
                                <CommentItem
                                    key={reply.id}
                                    comment={reply}
                                    currentUserId={currentUserId}
                                    depth={depth + 1}
                                    repliesByParent={repliesByParent}
                                    onReply={onReply}
                                    onEdit={onEdit}
                                    onDelete={onDelete}
                                    onReactComment={onReactComment}
                                    onLoadReplies={onLoadReplies}
                                />
                            ))}
                        </div>
                    ) : null}
                </div>
            </div>
        </div>
    )
}

"use client"

import React from "react"
import { cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { REACTIONS } from "./constants"
import { ReactionEmoji } from "./ReactionEmoji"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"

/** Props for {@link FacebookReactionSelector}. */
export interface FacebookReactionSelectorProps {
    /** The viewer's current reaction, highlighted in the bar (null = none). */
    active?: ReactionType | null
    /** Called with the picked emotion. */
    onSelect: (type: ReactionType) => void
}

/**
 * Facebook-style reaction picker bar ΓÇö the six emotions in a row, each scaling up and
 * lifting with its name floating above on hover, popping in with a slight stagger when
 * the bar appears.
 *
 * Reimplemented natively (native emoji glyphs + CSS keyframe `reactionPop`, NO third-party
 * reaction library) so it follows our design tokens + dark mode. The pop-in animation sits
 * on the button while the hover scale sits on an inner span, so the two transforms never
 * clash. Render inside the reaction Popover; selection is delegated via `onSelect`.
 *
 * @param props - {@link FacebookReactionSelectorProps}
 */
export const FacebookReactionSelector = ({ active, onSelect}: FacebookReactionSelectorProps) => {
    const t = useTranslations()

    return (
        <div className={"flex items-center gap-1"}>
            {REACTIONS.map((reaction, index) => {
                const label = t(reaction.labelKey)
                return (
                    <button
                        key={reaction.type}
                        type="button"
                        aria-label={label}
                        aria-pressed={active === reaction.type}
                        onClick={() => onSelect(reaction.type)}
                        // each emoji bounces in slightly after the previous one
                        style={{ animationDelay: `${index * 35}ms` }}
                        className={cn(
                            "group/fbreact relative flex animate-[reactionPop_220ms_cubic-bezier(0.34,1.56,0.64,1)_both]",
                            "cursor-pointer items-center justify-center rounded-full p-1 outline-none",
                            "focus-visible:ring-2 focus-visible:ring-accent",
                            active === reaction.type ? "bg-accent-soft" : undefined,
                        )}
                    >
                        {/* reaction name floats above on hover, in the style of Facebook */}
                        <span className="pointer-events-none absolute -top-7 left-1/2 -translate-x-1/2 scale-90 whitespace-nowrap rounded-full bg-foreground px-2 py-0 text-[10px] font-medium text-background opacity-0 transition-all duration-150 group-hover/fbreact:scale-100 group-hover/fbreact:opacity-100">
                            {label}
                        </span>
                        {/* emoji scales up + lifts on hover (transform isolated from the pop-in) */}
                        <span className="block origin-bottom transition-transform duration-150 ease-out group-hover/fbreact:-translate-y-1 group-hover/fbreact:scale-[1.45]">
                            <ReactionEmoji descriptor={reaction} size="md" />
                        </span>
                    </button>
                )
            })}
        </div>
    )
}

