/** Visual size for {@link ReactionEmoji}. */
export type ReactionEmojiSize = "xs" | "sm" | "md" | "lg"

/** Size token ΓåÆ square pixel size class (width + height). */
const SIZE_CLASS: Record<ReactionEmojiSize, string> = {
    xs: "size-4",
    sm: "size-5",
    md: "size-7",
