"use client"

import React, { useMemo } from "react"
import { Button, Label, Spinner, Typography, cn } from "@heroui/react"
import { ChatsCircleIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { CommentComposer } from "./CommentComposer"
import { CommentItem } from "./CommentItem"
import { ReactionType, type CommentNode } from "@/modules/api/graphql/queries/types/discussion"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"

export * from "./ReactionBar"
export * from "./ReactionEmoji"
export * from "./FacebookReactionSelector"
export * from "./CommentComposer"
export * from "./CommentItem"
export * from "./InteractionBar"
export * from "./constants"

/** Props for {@link Discussion}. */
export interface DiscussionProps extends WithClassNames<undefined> {
    /** Current viewer id (drives owner-only actions); null when unknown. */
    currentUserId: string | null
    /** Current viewer identity for the composer avatar; null when signed out. */
    currentUser: { username: string, avatar?: string } | null
    /** Top-level comments for the content. */
    comments: Array<CommentNode>
    /** Total top-level comment count (for the heading). */
    total: number
    /** Whether the first page of comments is still loading. */
    isLoading: boolean
    /** Replies keyed by parent comment id (lazily populated). */
    repliesByParent: Record<string, Array<CommentNode>>
    /** Post a new top-level comment. */
    onSubmitComment: (body: string) => void
    /** Post a reply under a parent comment. */
    onReply: (parentId: string, body: string) => void
    /** Edit a comment body (author only). */
    onEdit: (commentId: string, body: string) => void
    /** Soft-delete a comment (author only). */
    onDelete: (commentId: string) => void
    /** React to a comment (null removes the reaction). */
    onReactComment: (commentId: string, type: ReactionType | null) => void
    /** Lazily load the replies of a parent comment. */
    onLoadReplies: (parentId: string) => void
    /** Whether more top-level comment pages remain to load. */
    hasMore?: boolean
    /** Whether the next page is currently loading. */
    isLoadingMore?: boolean
    /** Load the next page of top-level comments. */
    onLoadMore?: () => void
}

/**
 * Bottom-of-lesson discussion zone ΓÇö FRAMELESS: a label ("Discussion ┬╖ N") + an honest
 * "archive line" (how many of this lesson's questions already have an answer ΓÇö the
 * value compounds as more cohorts pass through) above an avatar-led composer and the
 * threaded comment list, sitting directly on the page canvas (no card) so it doesn't
 * stack a second bordered surface under the reading "paper" card. The content reaction
 * picker is NOT here ΓÇö it lives in the reading-card footer
 * ({@link import("@/components/blocks/learn/lesson/ContentBody/ContentBodyV2/Discussion/ContentReactionBar").ContentReactionBar}).
 *
 * Presentational: receives all data + callbacks from a container; holds no data hooks.
 * The archive line is computed from the currently-loaded top-level comments (an honest,
 * real count ΓÇö not a fabricated aggregate); it only under-counts before "load more" is
 * exhausted, same tradeoff as the course-wide Q&A roll-up's answered count.
 * @param props - {@link DiscussionProps}
 */
export const Discussion = ({
    currentUserId,
    currentUser,
    comments,
    total,
    isLoading,
    repliesByParent,
    onSubmitComment,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies,
    hasMore,
    isLoadingMore,
    onLoadMore,
    className,
}: DiscussionProps) => {
    const t = useTranslations()

    // real (not fabricated) count of currently-loaded top-level questions that already
    // have at least one reply ΓÇö the "compounds over time" answer archive
    const answeredCount = useMemo(
        () => comments.filter((comment) => comment.replyCount > 0).length,
        [comments],
    )

    return (
        <section className={cn("flex flex-col gap-3", className)}>
            {/* ΓöÇΓöÇ label + archive line + composer (related ΓåÆ gap-3) ΓöÇΓöÇ */}
            <div className="flex flex-col gap-3">
                <div className="flex flex-col gap-1">
                    <div className="flex items-center gap-2">
                        <ChatsCircleIcon aria-hidden focusable="false" className="size-5 text-muted" />
                        <Label>{t("discussion.title", { count: total })}</Label>
                    </div>
                    {total > 0 ? (
                        <Typography type="body-xs" color="muted">
                            {t("discussion.archiveLine", { answered: answeredCount, total })}
                        </Typography>
                    ) : null}
                </div>
                {/* avatar-led composer: collapses to a slim pill until focused */}
                <CommentComposer onSubmit={onSubmitComment} currentUser={currentUser} collapsible />
            </div>

            {/* ΓöÇΓöÇ comment list / loading / empty states ΓöÇΓöÇ */}
            {isLoading ? (
                <div className="flex justify-center py-6">
                    <Spinner />
                </div>
            ) : comments.length === 0 ? (
                <AsyncContentEmpty
                    icon={ChatsCircleIcon}
                    title={t("discussion.empty")}
                    description={t("discussion.emptyHint")}
                />
            ) : (
                <div className="flex flex-col gap-3">
                    {comments.map((comment) => (
                        <CommentItem
                            key={comment.id}
                            comment={comment}
                            currentUserId={currentUserId}
                            depth={0}
                            repliesByParent={repliesByParent}
                            onReply={onReply}
                            onEdit={onEdit}
                            onDelete={onDelete}
                            onReactComment={onReactComment}
                            onLoadReplies={onLoadReplies}
                        />
                    ))}
                    {hasMore ? (
                        <Button
                            variant="tertiary"
                            className="self-center text-sm text-accent-soft-foreground"
                            isDisabled={isLoadingMore}
                            onPress={onLoadMore}
                        >
                            {isLoadingMore ? <Spinner size="sm" /> : t("discussion.loadMore")}
                        </Button>
                    ) : null}
                </div>
            )}
        </section>
    )
}

"use client"

import {
    UserMinusIcon,
    UserPlusIcon,
} from "@phosphor-icons/react"
import React from "react"
import {
    Button,
    cn,
    Spinner,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
/** Props for {@link FollowButton}. */
export interface FollowButtonProps {
    /** Current follow state (owned by the parent). */
    following: boolean
    /** Invoked when the button is pressed; the parent runs the mutation. */
    onToggle?: () => void
    /** True while the parent's toggle request is in flight. */
    isPending?: boolean
    /**
     * Quiet mode for dense surfaces (leaderboards) where MANY follow buttons sit
     * next to a single primary CTA: drops the solid-accent look so the page keeps
     * exactly one primary (`accent-system` ΓÇö 1 primary per screen). Default off (a lone
     * follow, e.g. a profile hero, stays primary).
     */
    quiet?: boolean
}

/**
 * Reusable follow / unfollow toggle for another user.
 *
 * Presentational only: it renders the follow state and forwards presses to the
 * parent via `onToggle`. The parent (a layout container) owns the `setFollow`
 * mutation, the authoritative `following` value, and the in-flight `isPending`
 * flag ΓÇö per the reuseable = no-store/no-fetch rule.
 *
 * @param props - {@link FollowButtonProps}
 */
export const FollowButton = ({
    following,
    onToggle,
    isPending = false,
    quiet = false,
}: FollowButtonProps) => {
    const t = useTranslations()

    // loud (default): primary ΓåÆ secondary. quiet (dense boards): secondary ΓåÆ tertiary,
    // so a page of follow rows never competes with its one primary CTA.
    const variant = quiet
        ? (following ? "tertiary" : "secondary")
        : (following ? "secondary" : "primary")

    return (
        <Button
            variant={variant}
            size="sm"
            isDisabled={isPending}
            onPress={onToggle}
            className={cn("shrink-0")}
        >
            {isPending ? (
                <Spinner
                    color="current"
                    size="sm"
                />
            ) : following ? (
                <UserMinusIcon className="size-4" />
            ) : (
                <UserPlusIcon className="size-4" />
            )}
            {following ? t("follow.following") : t("follow.follow")}
        </Button>
    )
}

"use client"

import React, {
    useEffect,
    useState,
} from "react"

/** Brand + celebratory palette for the falling pieces. */
const COLORS = ["#d6006e", "#eab308", "#16a34a", "#3b82f6", "#f97316", "#a855f7"]

/** Props for {@link Confetti}. */
export interface ConfettiProps {
    /**
     * Bump this to fire a burst (e.g. a counter incremented on a win). `0` stays
     * idle; each distinct non-zero value fires exactly one burst.
     */
    fireKey: number
    /** Piece count (default 90). */
    count?: number
}

/** One falling piece's randomised layout. */
interface Piece {
    id: string
    left: number
    delay: number
    duration: number
    color: string
    width: number
    rotate: number
}

/**
 * A lightweight, dependency-free confetti burst ΓÇö a fixed, non-interactive overlay
 * that rains coloured pieces down the viewport once per `fireKey` change, then
 * clears itself. Pure CSS fall animation (no canvas, no library). Used to celebrate
 * a top-3 league finish when the viewer lands on a board where they've placed.
 *
 * @param props - {@link ConfettiProps}
 */
export const Confetti = ({
    fireKey,
    count = 90,
}: ConfettiProps) => {
    const [pieces, setPieces] = useState<Array<Piece>>([])

    useEffect(
        () => {
            if (!fireKey) {
                return
            }
            // randomise in the effect (client-only) so there is no SSR hydration drift
            const next: Array<Piece> = []
            for (let i = 0; i < count; i += 1) {
                next.push({
                    id: `${fireKey}-${i}`,
                    left: Math.random() * 100,
                    delay: Math.random() * 0.4,
                    duration: 2 + Math.random() * 1.5,
                    color: COLORS[i % COLORS.length],
                    width: 6 + Math.random() * 6,
                    rotate: Math.random() * 360,
                })
            }
            setPieces(next)
            const timer = window.setTimeout(() => setPieces([]), 4000)
            return () => window.clearTimeout(timer)
        },
        [fireKey, count],
    )

    if (pieces.length === 0) {
        return null
    }

    return (
        <div aria-hidden className="pointer-events-none fixed inset-0 z-50 overflow-hidden">
            <style>
                {"@keyframes starci-confetti-fall{0%{transform:translateY(-12vh) rotate(0deg);opacity:1}100%{transform:translateY(112vh) rotate(720deg);opacity:.85}}"}
            </style>
            {pieces.map((piece) => (
                <span
                    key={piece.id}
                    className="absolute top-0 rounded-[2px]"
                    style={{
                        left: `${piece.left}%`,
                        width: `${piece.width}px`,
                        height: `${piece.width * 0.6}px`,
                        backgroundColor: piece.color,
                        animation: `starci-confetti-fall ${piece.duration}s linear ${piece.delay}s forwards`,
                    }}
                />
            ))}
        </div>
    )
}

import React from "react"
import { ContinueCardItem } from "@/components/blocks/learn/ContinueCard"
import { AsyncContent } from "@/components/composites/async/AsyncContent"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { Button } from "@/components/atoms/buttons/Button"

/**
 * `ContinueLearning` (dashboard) ΓÇö the "Continue learning" slot: up to 3 resume
 * targets (lessons lead, at most one in-progress challenge as a nudge), or an
 * onboarding CTA when there is nothing to resume. Three leaves: `Content`
 * (1ΓÇô3 tiles in a `Grid`), `Empty` (`AsyncContentEmpty`, wording forks on
 * `hasCourses`), and `Loading` (a 3-tile skeleton grid).
 */

/** Resume target kind ΓÇö the ONLY thing that changes the card's subtitle wording. */
export type ContinueLearningItemKind = "lesson" | "challenge"

/** One "pick up where you left off" resume target. */
export interface ContinueLearningItem {
    /** Opaque id ΓÇö the block never resolves it itself, that's the caller's job on press. */
    id: string
    /** Title to show ΓÇö already the display string, no further formatting here. */
    title: string
    /** Lesson vs. challenge ΓÇö drives the subtitle word only. */
    kind: ContinueLearningItemKind
}

/** Props for {@link ContinueLearning}. */
export interface ContinueLearningProps {
    /** Resume targets, already capped + de-duplicated by the caller (┬º14d.1 ΓÇö this block does not slice). */
    items: ReadonlyArray<ContinueLearningItem>
    /** `true` ΓåÆ the viewer has joined at least one course (decides the empty leaf's wording). */
    hasCourses: boolean
    /** `true` while the underlying leaf queries are loading (feeds the Loading leaf). */
    isLoading: boolean
    /** Fired with an item's `id` when its card is pressed. */
    onSelectItem: (id: string) => void
    /** Fired when the onboarding CTA is pressed (both empty wordings share one action). */
    onBrowseCourses: () => void
}

/** Subtitle word per kind ΓÇö the block's own wording (┬º14d.1: design never sees "lesson"/"challenge"). */
const KIND_LABEL: Record<ContinueLearningItemKind, string> = {
    lesson: "Currently reading",
    challenge: "Challenge in progress",
}

/** Placeholder tiles for the guessed 3-card skeleton grid (┬º12c) ΓÇö never carry a press handler. */
const SKELETON_ITEMS: Array<ContinueLearningItem> = [
    { id: "skeleton-0", title: "", kind: "lesson" },
    { id: "skeleton-1", title: "", kind: "lesson" },
    { id: "skeleton-2", title: "", kind: "lesson" },
]

/**
 * The dashboard's "Continue learning" content. See the file header for the full
 * leaf/state contract.
 *
 * @param props - {@link ContinueLearningProps}
 */
const ContinueLearning = ({
    items,
    hasCourses,
    isLoading,
    onSelectItem,
    onBrowseCourses,
}: ContinueLearningProps) => {
    const usingPlaceholders = isLoading && items.length === 0
    const source = usingPlaceholders ? SKELETON_ITEMS : items

    const tiles: Array<GridItem> = source.map((item) => ({
        key: item.id,
        content: () => (
            <ContinueCardItem
                isSkeleton={usingPlaceholders}
                title={item.title}
                subtitle={KIND_LABEL[item.kind]}
                onPress={usingPlaceholders ? undefined : () => onSelectItem(item.id)}
            />
        ),
    }))

    return (
        <div>
            <AsyncContent
                isLoading={isLoading && items.length === 0}
                skeleton={() => <Grid items={tiles} columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                />}
                isEmpty={!isLoading && items.length === 0}
                emptyContent={{
                    title: hasCourses
                        ? "You haven't read any lessons or attempted any challenges yet."
                        : "You haven't joined any courses yet.",
                    description: hasCourses
                        ? "Start a lesson so it shows up here under \"Continue learning\"."
                        : undefined,
                    action: () => (
                        <Button
                            variant="primary"
                            size="sm"
                            label="Browse courses"
                            onPress={onBrowseCourses}

                        />
                    ),

                }}
                content={() => <Grid items={tiles} columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                />}
            />
        </div>
    )
}

export { ContinueLearning }

"use client"

import React from "react"
import {
    Link,
    Typography,
    cn,
} from "@heroui/react"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import type { VerdictBand } from "@/components/blocks/cards/verdict-band"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { UserCell } from "@/components/composites/lists/UserCell"
import {
    placeMedalIcon,
    rankBadgeIcon,
} from "@/components/blocks/dashboard/rankBadge"
import { StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One normalised leaderboard row (the container maps its query data into this). */
export interface LeaderboardRow {
    /** React key + stable id. */
    key: string
    /** 1-based rank ΓÇö Γëñ3 renders a place medal, else the number. */
    rank: number
    /** Display username (null ΓåÆ dash). */
    username: string | null
    /** Avatar URL (null ΓåÆ generated fallback). */
    avatar?: string | null
    /** Pre-formatted trailing value (e.g. "640 pts" / "1420 XP"). */
    valueLabel: React.ReactNode
    /** True ΓåÆ highlight as the viewer (accent value + `meLabel` suffix). */
    isMe?: boolean
    /** Profile link target; omit ΓåÆ the identity is non-clickable. */
    profileHref?: string
    /** Context action at the far right (rank-delta caret / follow button). */
    trailing?: React.ReactNode
    /**
     * Optional left band (`SurfaceListCardItem.withVerdict`, `card.md` ┬º3i) ΓÇö a DATA
     * signal on this row (e.g. the weekly cohort's promote/demote zone). Pass the
     * canonical {@link VerdictBand} (`variant`/`color`) ΓÇö NOT a free-form `className`,
     * which `verdictBandClassName` silently ignores (was the "invisible border" bug).
     */
    verdict?: VerdictBand
}

/** The viewer's own standing shown as the card's header line. */
export interface LeaderboardStanding {
    /** Viewer's rank ΓÇö drives the leading {@link IconTile} badge (medal Γëñ3 / cup 4+). */
    rank: number
    /** Primary line (e.g. "Rank #1 ┬╖ top 20%"). */
    primary: React.ReactNode
    /** Secondary muted line (e.g. "640 pts ┬╖ Resets in 1 day 18 hours"). */
    secondary?: React.ReactNode
}

/** Props for {@link LeaderboardListCard}. */
export interface LeaderboardListCardProps extends WithClassNames<undefined> {
    /**
     * Bare mode ΓÇö skip the {@link LabeledCard} frame (`title`/`onSeeMore` ignored) and
     * render just the standing + list. For a full page that already has its own
     * `PageHeader` (the course leaderboard); the dashboard cards leave it off.
     */
    bare?: boolean
    /** Card label (LabeledCard heading). Ignored when `bare`. */
    title?: string
    /** "See more" handler (opens the full board). */
    onSeeMore?: () => void
    /** "See more" label. */
    seeMoreLabel?: string
    /** The viewer's own standing header line (omit when they have no rank). */
    standing?: LeaderboardStanding
    /**
     * Optional node between the standing and the list ΓÇö e.g. a `Podium` on a spacious
     * page (course leaderboard). Dashboard cards omit it (compact, no podium).
     */
    topSlot?: React.ReactNode
    /** The ranked rows (top-N slice; when a podium is in `topSlot`, pass rank 4+). */
    rows: Array<LeaderboardRow>
    /** Pinned self-row when the viewer sits below the shown slice. */
    selfRow?: LeaderboardRow
    /** Ellipsis label above the pinned self-row (e.g. "41 more people"). */
    ellipsisLabel?: React.ReactNode
    /** "You" suffix appended to the viewer's own row name. */
    meLabel?: React.ReactNode
}

/**
 * The ONE shared render for a dashboard leaderboard preview ΓÇö a {@link LabeledCard}
 * with the viewer's own standing (rank-driven {@link IconTile} badge: medal for the
 * podium, cup below) over a bordered {@link SurfaceListCard} of ranked rows (top-3
 * wear place medals). Both the weekly "Weekly league" and the global "Top learners"
 * cards map their data into this, so they render IDENTICALLY (teacher 2026-07-17 "2
 * identical sections"); only the per-context `trailing` slot (rank-delta caret vs follow)
 * and the emergent badge differ. Presentational + props-only; containers own the fetch.
 *
 * @param props - {@link LeaderboardListCardProps}
 */
export const LeaderboardListCard = ({
    bare = false,
    title,
    onSeeMore,
    seeMoreLabel,
    standing,
    topSlot,
    rows,
    selfRow,
    ellipsisLabel,
    meLabel,
    className,
}: LeaderboardListCardProps) => {
    /** Render one row (shared by the ranked list and the pinned self-row). */
    const renderRow = (row: LeaderboardRow) => {
        const displayName = row.isMe && row.username && meLabel
            ? `${row.username} ┬╖ ${meLabel}`
            : (row.username ?? "")
        const identity = (
            <UserCell
                username={displayName}
                avatar={row.avatar ?? undefined}
                isOwnRow={row.isMe }
            />
        )
        return (
            <SurfaceListCardItem key={row.key} withVerdict={row.verdict}>
                <div className="flex items-center gap-3">
                    {/* top-3 ΓåÆ place medal (≡ƒÑç≡ƒÑê≡ƒÑë); rank 4+ ΓåÆ plain number. Number matches the
                        medal's w-6 CENTERED slot (teacher 2026-07-17 "4 and 5 still misaligned") at the same
                        text-sm foreground as the name (same-row same-size, `visual-hierarchy`). */}
                    {row.rank <= 3 ? (
                        <span className="flex w-6 shrink-0 items-center justify-center">
                            {placeMedalIcon(row.rank)}
                        </span>
                    ) : (
                        <span className="flex w-6 shrink-0 items-center justify-center text-sm text-foreground">
                            {row.rank}
                        </span>
                    )}
                    {row.profileHref ? (
                        <Link
                            href={row.profileHref}
                            className="flex min-w-0 flex-1 items-center text-foreground no-underline transition-opacity hover:opacity-60"
                        >
                            {identity}
                        </Link>
                    ) : (
                        <div className="flex min-w-0 flex-1 items-center">{identity}</div>
                    )}
                    {/* value = meta ΓåÆ always muted + right-aligned tabular so the XP column
                        lines up across rows (teacher 2026-07-17: accent moves to the NAME, value
                        stays muted). */}
                    <Typography
                        type="body-sm"
                        color="muted"
                        className="shrink-0 text-right tabular-nums"
                    >
                        {row.valueLabel}
                    </Typography>
                    {row.trailing ? (
                        <div className="flex shrink-0 items-center">{row.trailing}</div>
                    ) : null}
                </div>
            </SurfaceListCardItem>
        )
    }

    const contentItems = [
        ...(standing
            ? [() => (
                <div className="flex items-center gap-3">
                    <IconTile icon={rankBadgeIcon(standing.rank)} tone="neutral" size="sm" />
                    <div className="flex min-w-0 flex-col">
                        <Typography type="body-sm" weight="bold" truncate>
                            {standing.primary}
                        </Typography>
                        {standing.secondary ? (
                            <Typography type="body-xs" color="muted">
                                {standing.secondary}
                            </Typography>
                        ) : null}
                    </div>
                </div>
            )]
            : []),
        ...(topSlot ? [() => <>{topSlot}</>] : []),
        ...(rows.length > 0 || selfRow
            ? [() => (
                <SurfaceListCard bordered>
                    {rows.map(renderRow)}
                    {selfRow ? (
                        <>
                            <SurfaceListCardItem>
                                <div className="flex min-h-8 items-center gap-3">
                                    <span className="flex w-6 shrink-0 items-center justify-center text-base leading-none tracking-widest text-muted">
                                        Γï»
                                    </span>
                                    <Typography type="body-sm" color="muted">
                                        {ellipsisLabel}
                                    </Typography>
                                </div>
                            </SurfaceListCardItem>
                            {renderRow(selfRow)}
                        </>
                    ) : null}
                </SurfaceListCard>
            )]
            : []),
    ]

    // bare ΓåÆ the page owns the frame (PageHeader); dashboard cards keep the LabeledCard
    if (bare) {
        return (
            <div className={cn("flex flex-col gap-3", className)}>
                {contentItems.map((Item, index) => (
                    <Item key={index} />
                ))}
            </div>
        )
    }

    return (
        <LabeledCard
            identity={{ tier: "block", component: "LeaderboardListCard" }}
            // `title` is only ever omitted in `bare` mode, which already returned above ΓÇö
            // the fallback here is a type-safety guard, not a real state either caller hits.
            label={title ?? ""}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
        >
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Standing, optional podium, and cohort list are peer sections in one leaderboard ΓÇö not block-boundary, because they stay inside one card group."
                items={contentItems}
            />
        </LabeledCard>
    )
}

"use client"

import React from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import {
    UserAvatar,
} from "@/components/blocks/identity/UserAvatar"
import {
    RankDeltaCaret,
} from "@/components/blocks/profile/RankDeltaCaret"
/** One podium finisher (top-3). */
export interface PodiumEntry {
    /** 1-based rank (1 ┬╖ 2 ┬╖ 3). */
    rank: number
    /** Display username (null ΓåÆ dash). */
    username: string | null
    /** Avatar URL (null ΓåÆ generated fallback). */
    avatar: string | null
    /** Pre-formatted points label (e.g. "1420 pts"). */
    pointsLabel: React.ReactNode
    /** True when this finisher is the viewer ΓåÆ ring-accent avatar + accent name + label. */
    isMe?: boolean
    /**
     * Rank movement vs last week (`>0` climbed, `<0` dropped, `0`/`null` unchanged) ΓÇö
     * shown as a `Γû┤Γû╛N` caret ABOVE the avatar when there's real movement. Omit for a
     * board that has no weekly baseline (e.g. the all-time global tab).
     */
    rankDelta?: number | null
}

/** Props for the {@link Podium} block. */
export interface PodiumProps {
    /** Top finishers bestΓåÆworst; at most 3 are shown. */
    entries: Array<PodiumEntry>
    /** Optional "you" label appended to the viewer's finisher (e.g. `t("...you")`). */
    meLabel?: React.ReactNode
}

/**
 * Top-3 leaderboard podium ΓÇö the classic winners' dais (2nd ┬╖ 1st ┬╖ 3rd, the
 * champion centered and raised) that gives a global board its "who's winning"
 * moment. Presentational + props-only; the board owns the data. Accent lives
 * only on the champion's step (a single focal point, not a flood ΓÇö
 * `accent-system`).
 *
 * @param props - {@link PodiumProps}
 */
export const Podium = ({
    entries,
    meLabel}: PodiumProps) => {
    const top = entries.slice(0, 3)
    // visual order: runner-up ┬╖ champion ┬╖ third ΓÇö champion centered + raised
    const ordered = [top[1], top[0], top[2]].filter(Boolean) as Array<PodiumEntry>

    return (
        <div className={"flex items-end justify-center gap-3"}>
            {ordered.map((entry) => {
                const isChampion = entry.rank === 1
                return (
                    <div key={entry.rank} className="flex flex-col items-center gap-2">
                        {/* rank movement above the avatar ΓÇö only when it actually moved */}
                        {entry.rankDelta ? (
                            <RankDeltaCaret delta={entry.rankDelta} />
                        ) : null}
                        <UserAvatar
                            // the viewer's own avatar is ringed (accent-system ┬º3 "mine"
                            // = ring + value accent, NOT a filled step)
                            className={cn(
                                "shrink-0",
                                isChampion ? "size-14" : "size-12",
                                entry.isMe && "ring-2 ring-accent ring-offset-2 ring-offset-surface",
                            )}
                            username={entry.username ?? ""}
                            avatar={entry.avatar}
                            seed={entry.username ?? String(entry.rank)}
                        />
                        <div className="flex w-20 flex-col items-center">
                            <Typography
                                type="body-sm"
                                weight="medium"
                                truncate
                                className={cn("max-w-full", entry.isMe && "text-accent-soft-foreground")}
                            >
                                {entry.username ?? "ΓÇö"}
                                {entry.isMe && meLabel ? <> ┬╖ {meLabel}</> : null}
                            </Typography>
                            <Typography type="body-xs" color="muted">
                                {entry.pointsLabel}
                            </Typography>
                        </div>
                        {/* the dais step ΓÇö champion raised, marked by a ring + accent
                            number (NOT an accent fill: accent-system ┬º5 + the
                            LeaderboardPodium ruling ΓÇö the winner's platform is not tinted) */}
                        <div
                            className={cn(
                                "flex w-20 items-center justify-center rounded-t-2xl font-bold",
                                isChampion
                                    ? "h-16 bg-surface text-accent ring-2 ring-inset ring-accent"
                                    : "h-10 bg-surface-secondary text-foreground",
                            )}
                        >
                            {entry.rank}
                        </div>
                    </div>
                )
            })}
        </div>
    )
}

export default Podium

"use client"

import React from "react"
import { Button, Typography } from "@heroui/react"
import {
    ArrowRightIcon,
} from "@phosphor-icons/react"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
/** Goal-gradient progress toward the next rank/tier, shown as a thin meter. */
export interface StandingHeroProgress {
    /** Fill ratio, clamped to `0..1`. */
    ratio: number
    /** Muted line above the meter (e.g. "40 more points to reach the promotion zone"). */
    label: string
}

/** Props for the {@link StandingHeroCard} block. */
export interface StandingHeroCardProps {
    /** Leading badge/icon ΓÇö a `LeagueTierBadge` (weekly) or a scope icon (global). */
    badge?: React.ReactNode
    /** Primary standing line (e.g. "Rank #1 ┬╖ Bronze" / "Rank #9 platform-wide"). */
    rankLabel: React.ReactNode
    /** Secondary meta under the rank ΓÇö points ┬╖ movement ┬╖ reset countdown. */
    meta?: React.ReactNode
    /** Optional goal-gradient meter toward the next rank/tier. */
    progress?: StandingHeroProgress
    /** CTA label ΓÇö the north-star funnel to courses ("Do challenges to climb the ranks"). */
    ctaLabel: React.ReactNode
    /** CTA press handler. */
    onCta: () => void
}

/**
 * The "your standing" hero at the top of each leaderboard board ΓÇö the emotional
 * hook + the ONE conversion action. Shows the viewer's own rank/tier/points, an
 * optional goal-gradient meter toward the next rank (motivation), and a single
 * primary CTA that funnels to courses (the north-star: climb by learning).
 *
 * Presentational + props-only; the board owns the data + the CTA target. Accent
 * lives only in the meter fill + the primary CTA (a bounded hero, NOT an
 * accent-flooded section ΓÇö `accent-system`).
 *
 * @param props - {@link StandingHeroCardProps}
 */
export const StandingHeroCard = ({
    badge,
    rankLabel,
    meta,
    progress,
    ctaLabel,
    onCta}: StandingHeroCardProps) => (
    <div className={"flex flex-col gap-4 rounded-3xl bg-surface p-5 shadow-surface"}>
        <div className="flex items-center gap-4">
            {badge ? <div className="shrink-0">{badge}</div> : null}
            <div className="flex min-w-0 flex-col gap-1">
                <Typography type="h6" weight="bold" truncate>
                    {rankLabel}
                </Typography>
                {meta ? (
                    <Typography type="body-sm" color="muted">
                        {meta}
                    </Typography>
                ) : null}
            </div>
        </div>

        {progress ? (
            /* canonical goal-gradient meter (ProgressMeter) ΓÇö label above + accent fill */
            <ProgressMeter
                value={Math.min(1, Math.max(0, progress.ratio)) * 100}
                max={100}
                label={progress.label}
            />
        ) : null}

        <Button variant="primary" className="w-fit" onPress={onCta}>
            {ctaLabel}
            <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
        </Button>
    </div>
)

export default StandingHeroCard

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { AsyncContent } from "@/components/composites/async/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Chip } from "@/components/atoms/chips/Chip"
import { Button } from "@/components/atoms/buttons/Button"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * BLOCK ΓÇö `WeeklyChallengeCard`: "Weekly Challenge" ΓÇö the featured challenge of
 * the week. See the component's own file header for the full contract; this
 * file only adds the states.
 *
 * LEAF by STRUCTURE (┬º14d.2): whether the viewer already passed, already
 * claimed, or the leaderboard is short, are all DATA conditions of the same
 * status row/list ΓÇö never a different shape this block draws ΓÇö so this block
 * has exactly ONE leaf ("Content"), the same shape `LeaderboardBoard`'s single
 * `Board` leaf uses.
 */

/** One leaderboard row: a finisher who already passed this week's challenge. */
export interface WeeklyChallengeLeaderboardEntry {
    /** Stable React key ΓÇö the finisher's username. */
    key: string
    /** Account username; drives the avatar fallback (same contract as {@link UserCell}). */
    username: string
    /** Uploaded avatar URL, or `null`/omitted ΓÇö a generated default is shown instead. */
    avatar?: string | null
    /** Already-worded "x ago" label (e.g. "5 minutes ago"). */
    passedAtLabel: string
}

/** The currently featured weekly-challenge event. */
export interface WeeklyChallengeData {
    /** Title of the featured challenge. */
    title: string
    /** Fired from the title AND the "Try it now" prompt ΓÇö the caller already resolved the route. Omit when not routable. */
    onOpenChallenge?: () => void
    /** Already-worded countdown to the event's close (e.g. "2 days 6 hours left"). Omit while unknown. */
    endsInLabel?: string
    /** Whether the viewer has already passed the challenge this week. */
    viewerPassed: boolean
    /** Whether the viewer already claimed the reward this week. Ignored unless `viewerPassed`. */
    claimed: boolean
    /** Coin reward for claiming; `null` when the viewer hasn't passed yet. */
    coinReward: number | null
    /** `true` -> the claim mutation is in flight ΓÇö disables + spins the claim button. */
    isClaiming?: boolean
    /** Fired when the viewer presses the claim button. Required whenever `viewerPassed && !claimed`. */
    onClaim?: () => void
    /** Total number of users who have passed so far. */
    passedCount: number
    /** Top finishers (already capped by the caller), newest first. */
    leaderboard: Array<WeeklyChallengeLeaderboardEntry>
}

/** Props for {@link WeeklyChallengeCard}. */
export interface WeeklyChallengeCardProps {
    /** True while the first load is running ΓÇö {@link AsyncContent}'s loading branch. */
    isLoading: boolean
    /** True (once loaded) -> no challenge event is currently active. */
    isEmpty: boolean
    /** Truthy -> the snapshot failed to load. Pass SWR's `error`. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry: () => void
    /** The featured challenge. Required once loaded and non-empty. */
    data?: WeeklyChallengeData
    /** `true` -> every atom this block owns switches to its own shimmer (data already loaded). */
    isSkeleton?: boolean
}

/** The title: a routable link when `onOpenChallenge` is set, plain bold text otherwise. */
const titleText = (data: WeeklyChallengeData, isSkeleton: boolean) =>
    data.onOpenChallenge ? (
        <Typography
            size="sm"
            isLink
            isSkeleton={isSkeleton}
            onPress={data.onOpenChallenge}
            text={data.title}

        />
    ) : (
        <Typography
            size="sm"
            weight="bold"
            isSkeleton={isSkeleton}
            text={data.title}

        />
    )

/** Right side of the status row: claimed chip, a pending claim button, or a "try now" prompt. */
const statusSlot = (data: WeeklyChallengeData, isSkeleton: boolean) => {
    if (isSkeleton) {
        return <Chip isSkeleton />
    }
    if (!data.viewerPassed) {
        return data.onOpenChallenge ? (
            <Typography
                size="xs"
                isLink
                onPress={data.onOpenChallenge}
                text="Try it now"

            />
        ) : null
    }
    if (data.claimed) {
        return (
            <Chip tone="success" text="Completed" />
        )
    }
    return (
        <Button
            variant="primary"
            size="sm"
            isPending={data.isClaiming}
            onPress={data.onClaim}
            label={`Claim ${data.coinReward ?? 0} coins`}
        />
    )
}

/** Builds one finisher's free-form `SurfaceCardList` content: the unchanged `UserCell`. */
const finisherItem = (entry: WeeklyChallengeLeaderboardEntry, isSkeleton: boolean): SurfaceCardListItem => ({
    key: entry.key,
    content: () => (
        <div>
            <UserCell
                username={entry.username}
                avatar={entry.avatar}
                trailing={({ isSkeleton: slotSkeleton }: SkeletonProps) => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={slotSkeleton}
                        text={slotSkeleton ? undefined : entry.passedAtLabel}

                    />
                )}
                isSkeleton={isSkeleton}

            />
        </div>
    ),
})

/** Fixed-shape placeholder rendered while {@link WeeklyChallengeCardProps.isLoading} ΓÇö no real event exists yet. */
const LOADING_DATA: WeeklyChallengeData = {
    title: "",
    viewerPassed: false,
    claimed: false,
    coinReward: null,
    passedCount: 0,
    leaderboard: Array.from({ length: 3 }, (_, index) => ({ key: `loading-${index}`, username: "", passedAtLabel: "" })),
}

/** Props for the internal {@link Content} tree ΓÇö reused for both the real render and the loading skeleton. */
interface ContentProps {
    data: WeeklyChallengeData
    isSkeleton: boolean
}

const Content = ({ data, isSkeleton }: ContentProps) => {
    const statusRow = (
        <StackH gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            justify="between" align="center" items={[
                () => (data.endsInLabel != null || isSkeleton ? (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : data.endsInLabel}

                    />
                ) : <span />),
                () => statusSlot(data, isSkeleton),
            ]} />
    )

    return (
        <StackV gap={4} items={[
            () => titleText(data, isSkeleton),
            () => statusRow,
            () => (
                <Typography
                    size="xs"
                    color="muted"
                    isSkeleton={isSkeleton}
                    text={isSkeleton ? undefined : `${data.passedCount} people have passed`}

                />
            ),
            ...(data.leaderboard.length > 0 ? [() => (
                <div>
                    <SurfaceCardList
                        variant="nested"
                        items={data.leaderboard.map((entry) => finisherItem(entry, isSkeleton))}

                    />
                </div>
            )] : []),
        ]} />
    )
}

/**
 * "Weekly Challenge" ΓÇö the featured weekly-challenge card. See the file header
 * for the full contract.
 *
 * @param props - {@link WeeklyChallengeCardProps}
 */
const WeeklyChallengeCard = ({
    isLoading,
    isEmpty,
    error,
    onRetry,
    data,
    isSkeleton = false,
}: WeeklyChallengeCardProps) => (
    <SurfaceCard
        identity={{ tier: "block", component: "WeeklyChallengeCard" }}
        label="Weekly Challenge"


        body={() => (
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => <Content data={LOADING_DATA} isSkeleton />}
                isEmpty={isEmpty}
                emptyContent={{
                    title: "No challenge is currently active",
                    description: "Check back next week for a new challenge.",
                }}
                error={error}
                errorContent={{
                    title: "Couldn't load the weekly challenge",
                    description: "Try again for the latest info.",
                    onRetry,
                    retryLabel: "Retry",
                }}
                content={() => (data ? (
                    <Content data={data} isSkeleton={isSkeleton} />
                ) : null)}
            />
        )}
    />
)

