"use client"

import React, { useEffect, useRef } from "react"
import { cn } from "@heroui/react"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { Composer } from "@/components/blocks/feed/Composer"
import type { ComposerProps } from "@/components/blocks/feed/Composer"

/** One message rendered by {@link ChatPanel}. */
export interface ChatPanelMessage {
    /** Stable id ΓÇö used as the React key. */
    id: string
    /** Author of the message ΓÇö maps to the {@link ChatBubble} alignment + tint. */
    role: "user" | "assistant"
    /** Message body (text or a markdown render), rendered inside the bubble. */
    content: React.ReactNode
    /**
     * Optional tool-result row rendered below the bubble, assistant-aligned ΓÇö e.g. a
     * {@link import("@/components/blocks/learn/ChatToolResult").ChatToolResult}. The
     * caller builds it; the panel only places it.
     */
    toolResult?: React.ReactNode
}

/**
 * Props for the {@link ChatPanel} block.
 *
 * A full chat surface: a scrollable message list, an optional typing indicator, an
 * empty-state slot, and a sticky-bottom {@link Composer}. Tier-3 presentational ΓÇö
 * all data + the composer wiring arrive via props; the only side-effect is an
 * auto-scroll-to-bottom effect on the list ref.
 */
export interface ChatPanelProps {
    /** The conversation, oldest first. Each entry renders one {@link ChatBubble}. */
    messages: Array<ChatPanelMessage>
    /** Props forwarded to the sticky-bottom {@link Composer} (controlled by the parent). */
    composer: ComposerProps
    /** When true, a three-dot typing indicator shows below the last message. */
    isTyping?: boolean
    /** Rendered centered in the list area when there are no messages. */
    emptyState?: React.ReactNode
}

/**
 * ChatPanel assembles the existing feed primitives into a complete chat surface:
 * a scrollable list of {@link ChatBubble}s (with optional tool-result rows
 * interleaved under assistant turns), an optional animated typing indicator, an
 * empty-state slot when the conversation is empty, and a sticky-bottom
 * {@link Composer} for the next message. The list auto-scrolls to the newest turn
 * whenever the messages or typing state change.
 *
 * Tier-3 presentational block: props-only, no store, no SWR. The parent owns the
 * message data and the composer's controlled draft.
 *
 * @param props - {@link ChatPanelProps}
 *
 * @example
 * <ChatPanel
 *   messages={turns}
 *   composer={{ value: draft, onChange: setDraft, onSubmit: send }}
 *   isTyping={isThinking}
 * />
 * @see Story: .storybook/stories/blocks/feed/ChatPanel/ChatPanel.stories
 */
export const ChatPanel = ({
    messages,
    composer,
    isTyping = false,
    emptyState}: ChatPanelProps) => {
    const listRef = useRef<HTMLDivElement>(null)

    // keep the newest turn in view as the conversation (or typing state) grows
    useEffect(() => {
        const element = listRef.current
        if (!element) {
            return
        }
        element.scrollTop = element.scrollHeight
    }, [messages, isTyping])

    const isEmpty = messages.length === 0

    return (
        <div
            className={cn("flex flex-col overflow-hidden rounded-3xl border border-default bg-surface",
                "h-[32rem]")}
        >
            {/* scrollable message list */}
            <div ref={listRef} className="flex-1 overflow-y-auto p-4">
                {isEmpty ? (
                    <div className="flex h-full items-center justify-center">
                        {emptyState}
                    </div>
                ) : (
                    <div className="flex flex-col gap-3">
                        {messages.map((message) => (
                            <div key={message.id} className="flex flex-col gap-2">
                                <ChatBubble role={message.role}>
                                    {message.content}
                                </ChatBubble>
                                {/* optional tool-result row, assistant-aligned under the bubble */}
                                {message.toolResult ? (
                                    <div className="flex justify-start">
                                        <div className="w-full max-w-[85%]">
                                            {message.toolResult}
                                        </div>
                                    </div>
                                ) : null}
                            </div>
                        ))}

                        {/* three-dot typing indicator on the assistant side */}
                        {isTyping ? (
                            <div className="flex justify-start">
                                <div className="flex items-center gap-1 rounded-2xl bg-surface-secondary px-3 py-3">
                                    {[0, 1, 2].map((dot) => (
                                        <span
                                            key={dot}
                                            className="size-1.5 animate-bounce rounded-full bg-muted"
                                            style={{ animationDelay: `${dot * 0.15}s` }}
                                        />
                                    ))}
                                </div>
                            </div>
                        ) : null}
                    </div>
                )}
            </div>

            {/* sticky-bottom composer */}
            <div className="border-t border-default p-3">
                <Composer {...composer} />
            </div>
        </div>
    )
}

"use client"

import React, { useState } from "react"
import { cn } from "@heroui/react"
import type { QueryCommunityCommentNode } from "@/modules/api/graphql/queries/types/community-comments"
import type { ReactionType } from "@/modules/api/graphql/queries/types/discussion"
import { CommunityCommentRow } from "@/components/blocks/feed/CommunityCommentRow"
import { Composer } from "@/components/blocks/feed/Composer"

/** Deepest level that still gets a visual indent rail; deeper replies render flush. */
const MAX_INDENT_DEPTH = 4

/**
 * One node in a {@link CommentThread}: everything {@link CommunityCommentRow} needs
 * (a {@link QueryCommunityCommentNode}, which already carries `id`) plus its nested
 * replies.
 */
export interface CommentThreadNode extends QueryCommunityCommentNode {
    /** Direct replies to this comment, rendered indented one level deeper. */
    replies?: Array<CommentThreadNode>
}

/**
 * Props for the {@link CommentThread} block.
 *
 * A nested comment thread built from {@link CommunityCommentRow}s plus a
 * {@link Composer} for both the root box and each inline reply. Tier-3
 * presentational ΓÇö the tree + callbacks arrive via props; the block owns only the
 * transient draft/reveal UI state.
 */
export interface CommentThreadProps {
    /** The comment tree, top-level nodes first. */
    comments: Array<CommentThreadNode>
    /**
     * Post a comment. `parentId` is the id of the comment being replied to, or
     * `null` for a new root comment from the top-level composer.
     */
    onReply: (parentId: string | null, text: string) => void
    /**
     * Pass-through of {@link CommunityCommentRow}'s react handler, keyed by comment
     * id ΓÇö pass the chosen emotion, or `null` to remove. Omit to render every row's
     * reaction bar READ-ONLY (e.g. a signed-out viewer).
     */
    onReact?: (commentId: string, type: ReactionType | null) => void
    /** Avatar url for the viewer, shown on the root + reply composers. */
    avatarSrc?: string
}

/** Props for the recursive {@link CommentThreadItem}. */
interface CommentThreadItemProps {
    /** The node to render (with its replies). */
    node: CommentThreadNode
    /** Nesting depth ΓÇö drives the capped indent rail. */
    depth: number
    /** See {@link CommentThreadProps.onReply}. */
    onReply: (parentId: string | null, text: string) => void
    /** See {@link CommentThreadProps.onReact}. */
    onReact?: (commentId: string, type: ReactionType | null) => void
    /** Avatar url for the inline reply composer. */
    avatarSrc?: string
}

/**
 * One comment plus its recursively-rendered replies. Owns only transient UI state
 * (the reply box's open flag + its draft); persistence is delegated upward.
 */
const CommentThreadItem = ({
    node,
    depth,
    onReply,
    onReact,
    avatarSrc,
}: CommentThreadItemProps) => {
    const [replying, setReplying] = useState(false)
    const [replyValue, setReplyValue] = useState("")

    // reveal-a-reply-box affordance, handed to the row's actions slot
    const replyAction = (
        <button
            type="button"
            onClick={() => setReplying((previous) => !previous)}
            className="cursor-pointer text-xs font-medium text-muted transition-colors hover:text-foreground"
        >
            Reply
        </button>
    )

    // submit the reply, clear the draft, and collapse the box
    const submitReply = () => {
        const text = replyValue.trim()
        if (!text) {
            return
        }
        onReply(node.id, text)
        setReplyValue("")
        setReplying(false)
    }

    const replies = node.replies ?? []

    return (
        <div
            className={cn(
                "flex flex-col gap-3",
                // indent nested replies with a guide rail, capped so deep threads stay readable
                depth > 0 && depth <= MAX_INDENT_DEPTH ? "border-l border-default pl-3 @app-sm:pl-4" : undefined,
            )}
        >
            <CommunityCommentRow
                comment={node}
                onReact={onReact ? (type) => onReact(node.id, type) : undefined}
                actions={replyAction}
            />

            {/* inline reply composer, revealed by the "Reply" affordance */}
            {replying ? (
                <Composer
                    value={replyValue}
                    onChange={setReplyValue}
                    onSubmit={submitReply}
                    avatarSrc={avatarSrc}
                    placeholder="Write a reply..."
                    submitLabel="Reply"
                    className="pl-9"
                />
            ) : null}

            {/* recursive reply subtree */}
            {replies.length > 0 ? (
                <div className="flex flex-col gap-3">
                    {replies.map((reply) => (
                        <CommentThreadItem
                            key={reply.id}
                            node={reply}
                            depth={depth + 1}
                            onReply={onReply}
                            onReact={onReact}
                            avatarSrc={avatarSrc}
                        />
                    ))}
                </div>
            ) : null}
        </div>
    )
}

/**
 * CommentThread assembles a nested discussion from the existing
 * {@link CommunityCommentRow} (one per node) and {@link Composer} (root box + each
 * inline reply). Replies indent one level per depth behind a guide rail that caps
 * after a few levels so deep threads stay readable; every node exposes a "Reply"
 * affordance that reveals its own reply composer, and a top-level composer adds a
 * root comment. Reaction handling is a straight pass-through to each row.
 *
 * Tier-3 presentational block: props-only, no store, no SWR. It owns only the
 * transient draft/reveal state of the composers; posting is delegated via
 * {@link CommentThreadProps.onReply}.
 *
 * @param props - {@link CommentThreadProps}
 *
 * @example
 * <CommentThread
 *   comments={tree}
 *   onReply={(parentId, text) => post(parentId, text)}
 *   onReact={(id, type) => react(id, type)}
 * />
 * @see Story: .storybook/stories/blocks/feed/CommentThread/CommentThread.stories
 */
export const CommentThread = ({
    comments,
    onReply,
    onReact,
    avatarSrc}: CommentThreadProps) => {
    const [rootValue, setRootValue] = useState("")

    // submit a new root comment (parentId = null), then clear the box
    const submitRoot = () => {
        const text = rootValue.trim()
        if (!text) {
            return
        }
        onReply(null, text)
        setRootValue("")
    }

    return (
        <div className={"flex flex-col gap-4"}>
            {/* top-level composer for a new root comment */}
            <Composer
                value={rootValue}
                onChange={setRootValue}
                onSubmit={submitRoot}
                avatarSrc={avatarSrc}
                placeholder="Write a comment..."
            />

            {/* the thread */}
            {comments.length > 0 ? (
                <div className="flex flex-col gap-3">
                    {comments.map((comment) => (
                        <CommentThreadItem
                            key={comment.id}
                            node={comment}
                            depth={0}
                            onReply={onReply}
                            onReact={onReact}
                            avatarSrc={avatarSrc}
                        />
                    ))}
                </div>
            ) : null}
        </div>
    )
}

import React from "react"
import { Typography } from "@heroui/react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { ReactionBar } from "../ReactionBar"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"
import type { QueryCommunityCommentNode } from "@/modules/api/graphql/queries/types/community-comments"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"

/** Props for {@link _CommunityCommentRow} ΓÇö presentational; labels already resolved. */
export interface CommunityCommentRowProps {
    /** The comment to render. */
    comment: QueryCommunityCommentNode
    /**
     * React handler ΓÇö pass the chosen emotion, or `null` to remove. Omit to render
     * the reaction bar READ-ONLY (e.g. when the viewer is signed out).
     */
    onReact?: (type: ReactionType | null) => void
    /**
     * Optional actions rendered below the body (e.g. reply / view-replies controls).
     * Supplied by the owning feature so the row stays presentational.
     */
    actions?: React.ReactNode
    /** Already-localized placeholder shown instead of the body when the comment is soft-deleted. */
    deletedLabel: string
    /** Already-localized relative "x minutes ago" timestamp. */
    timeAgoLabel: string
}

/**
