"use client"

import React, {
    useCallback,
    useState,
} from "react"
import { toast } from "@/modules/toast/toast"
import { useTranslations } from "next-intl"
import type {
    CvSubmissionFormValues,
} from "@/types"
import { mutateGetCVPresignedUrl } from "@/modules/api/graphql/mutations/mutation-get-cv-presigned-url"
import { mutateProcessCV } from "@/modules/api/graphql/mutations/mutation-process-cv"
import { useAppSelector } from "@/redux/hooks"
import { CVSubmissionForm } from "@/components/blocks/careers/CVSubmissionForm"
import { useRestWithToast } from "@/modules/toast/hooks"

/** Fraction of progress shown after each upload step (UI feedback only). */
const UPLOAD_PROGRESS = {
    /** Presigned-URL request issued. */
    presign: 20,
    /** S3 PUT in flight. */
    uploading: 40,
    /** Upload finished. */
    done: 100,
} as const

/** Props for {@link CvSubmission}. */
export type CvSubmissionProps = Record<string, never>
/**
 * CV submission container.
 *
 * Owns the business logic ΓÇö auth token (redux), upload/process state, the
 * presigned-URL + S3 upload + process mutations ΓÇö and renders the presentational
 * {@link CVSubmissionForm}. `"use client"` because it holds state + side effects.
 * @param props - {@link CvSubmissionProps}
 */
export const CvSubmission = () => {
    /** Keycloak access token used to authorize the API calls. */
    const token = useAppSelector((state) => state.keycloak.accessToken)
    /** Whether the S3 upload step is in progress. */
    const [isUploading, setIsUploading] = useState(false)
    /** Whether the backend processing step is in progress. */
    const [isProcessing, setIsProcessing] = useState(false)
    /** Upload progress percentage (0ΓÇô100). */
    const [uploadProgress, setUploadProgress] = useState(0)
    /** Name of the successfully uploaded file, or `null`. */
    const [uploadedFileName, setUploadedFileName] = useState<string | null>(null)
    /** S3 key of the successfully uploaded file, or `null`. */
    const [uploadedS3Key, setUploadedS3Key] = useState<string | null>(null)
    /** Localized toast wrapper for REST calls. */
    const runRest = useRestWithToast()
    const t = useTranslations("cv.submission")

    /** Upload the selected CV to S3 via a presigned URL. */
    const onSubmit = useCallback(
        async (
            values: CvSubmissionFormValues,
        ) => {
            if (!token) {
                console.error("Authentication token not found")
                return
            }
            if (!values.cv) {
                console.error("CV file is required")
                return
            }

            try {
                setIsUploading(true)
                setUploadProgress(0)
                setUploadedFileName(null)
                setUploadedS3Key(null)

                // Step 1: get a presigned URL from the backend
                setUploadProgress(UPLOAD_PROGRESS.presign)
                const presignedUrlResponse = await mutateGetCVPresignedUrl({
                    request: {
                        fileName: values.cv.name,
                        fileType: values.cv.type,
                    },
                    token,
                })
                if (!presignedUrlResponse.data?.getCVPresignedUrl?.data) {
                    throw new Error(
                        presignedUrlResponse.data?.getCVPresignedUrl?.message
                            || "Failed to get presigned URL",
                    )
                }
                const {
                    url: presignedUrl,
                    key: s3Key,
                } = presignedUrlResponse.data.getCVPresignedUrl.data

                // Step 2: upload the file to S3 via PUT
                setUploadProgress(UPLOAD_PROGRESS.uploading)
                const cvFile = values.cv
                const uploadResponse = await runRest(
                    async () => {
                        const response = await fetch(presignedUrl, {
                            method: "PUT",
                            body: cvFile,
                            headers: {
                                "Content-Type": cvFile.type,
                            },
                        })
                        if (!response.ok) {
                            throw new Error(
                                `Failed to upload file to S3: ${response.statusText}`,
                            )
                        }
                        return response
                    },
                    {
                        showSuccessToast: false,
                    },
                )
                if (!uploadResponse) {
                    return
                }

                setUploadProgress(UPLOAD_PROGRESS.done)
                setUploadedFileName(values.cv.name)
                setUploadedS3Key(s3Key)
                // the form resets itself via a useEffect once these two props are set
            } catch (error) {
                console.error("CV upload error:", error)
                toast.danger(t("uploadError"))
            } finally {
                setIsUploading(false)
            }
        },
        [
            token,
            runRest,
            t,
        ],
    )

    /** Trigger backend processing of the previously uploaded CV. */
    const onProcess = useCallback(
        async () => {
            if (!token) {
                console.error("Authentication token not found")
                return
            }
            if (!uploadedS3Key || !uploadedFileName) {
                console.error("Please upload CV first")
                return
            }

            try {
                setIsProcessing(true)
                const processResponse = await mutateProcessCV({
                    request: {
                        s3Key: uploadedS3Key,
                        fileName: uploadedFileName,
                    },
                    token,
                })
                if (!processResponse.data?.processCV?.data) {
                    throw new Error(
                        processResponse.data?.processCV?.message
                            || "Failed to process CV",
                    )
                }
            } catch (error) {
                console.error("CV process error:", error)
                toast.danger(t("processError"))
            } finally {
                setIsProcessing(false)
            }
        },
        [
            token,
            uploadedS3Key,
            uploadedFileName,
            t,
        ],
    )

    return (
        <div className={""}>
            <CVSubmissionForm
                isUploading={isUploading}
                isProcessing={isProcessing}
                uploadProgress={uploadProgress}
                uploadedFileName={uploadedFileName}
                uploadedS3Key={uploadedS3Key}
                onSubmit={onSubmit}
                onProcess={onProcess}
            />
        </div>
    )
}

"use client"

import React from "react"
import {
    cn,
} from "@heroui/react"
import {
    MedalIcon,
} from "@phosphor-icons/react"
import {
    BadgeImage,
} from "@/components/blocks/identity/BadgeImage"
import { getRank } from "@/modules/utils/rank"

/** Props for {@link MascotBadge}. */
export interface MascotBadgeProps {
    /** MinIO object key of the mascot art (bare animal, no baked frame). */
    objectKey: string
    /** Accessible name of the mascot. */
    name: string
    /** Whether the viewer has earned the badge at all. */
    earned: boolean
    /** Highest tier reached (1ΓÇô4), or null; drives the ring colour via rank. */
    tierReached: number | null
    /** Outer diameter in px (default 64). */
    size?: number
}

/**
 * A mascot badge: the bare animal art framed by a circular ring whose colour
 * encodes the viewer's rank (grey ΓåÆ bronze ΓåÆ silver ΓåÆ gold). Locked badges show
 * the art greyed-out inside a dashed neutral ring. One image per animal ΓÇö only
 * the ring colour changes across ranks, so art never has to be redrawn per tier.
 *
 * @param props - {@link MascotBadgeProps}
 */
export const MascotBadge = ({
    objectKey,
    name,
    earned,
    tierReached,
    size = 64}: MascotBadgeProps) => {
    const {
        rank,
        ring,
    } = getRank(earned, tierReached)
    // ring thickness + inner art scale with the badge so it reads at any size.
    // the art fills the full content box (box-sizing: border-box ΓåÆ already minus
    // the border) so the ring sits FLUSH against the mascot ΓÇö no transparent gap.
    const ringWidth = Math.max(3, Math.round(size * 0.06))
    const innerSize = size - ringWidth * 2

    return (
        <div
            className={cn(// clip the (slightly over-scaled) art to the ring so the mascot
                // hugs the ring with no transparent gap from the PNG's own padding
                "flex shrink-0 items-center justify-center overflow-hidden rounded-full",
                !rank && "border-dashed border-default-300")}
            style={{
                width: size,
                height: size,
                // earned ΓåÆ solid metallic rank ring; locked ΓåÆ dashed neutral (class)
                ...(rank
                    ? { border: `${ringWidth}px solid ${ring}` }
                    : { borderWidth: ringWidth }),
            }}
        >
            <BadgeImage
                objectKey={objectKey}
                size={innerSize}
                alt={name}
                className={cn(
                    // scale up to eat the art's built-in transparent margin so the
                    // visible animal reaches the ring (overflow clipped by parent)
                    "rounded-full object-cover scale-[1.18]",
                    !earned && "opacity-40 grayscale",
                )}
                fallback={(
                    <MedalIcon
                        width={innerSize}
                        height={innerSize}
                        className={cn(earned ? "text-warning-soft-foreground" : "text-default-400")}
                    />
                )}
            />
        </div>
    )
}

import React from "react"
import type { ComponentType, SVGProps } from "react"
import {
    CalendarBlankIcon,
    GithubLogoIcon,
    GlobeIcon,
    HandshakeIcon,
    LinkedinLogoIcon,
    MapPinIcon,
    PencilSimpleIcon,
    UserCheckIcon,
    UserPlusIcon,
} from "@phosphor-icons/react"
import { Divider } from "@/components/atoms/display/Divider"
import { ProfileRankAvatar } from "./ProfileRankAvatar"
import { ProfileFollowers } from "./ProfileFollowers"
import { ProfileBadges } from "./ProfileBadges"
import { ShareProfileButton } from "./ShareProfileButton"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import type { ButtonVariant } from "@/components/atoms/buttons/Button"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `ProfileHero` ΓÇö the identity sidebar for a person's profile page:
 * rank-framed avatar, name/@handle/role, bio, location + work-mode, follower
 * and badge social proof, one primary CTA (hire/follow/edit) + share, and a
 * github/linkedin/website/joined meta list. Composed from `SurfaceCard` around
 * `StackV`/`StackH`/`Cluster` holding `Avatar`/`Typography`/`Chip`/`Button`/
 * `Divider` plus `EnumChip`/`InlineIconLabel`. Two leaves: `Default` (every
 * optional row present; CTA/skeleton/follow-state are content states) and
 * `Minimal` (no rank/role/bio/location/work-mode/badges/social links ΓÇö losing
 * those removes real nodes, earning its own leaf).
 */

/** An icon passed as a COMPONENT (e.g. a Phosphor `*Icon`), rendered at the tile's own scale. Declared locally per atom convention (┬º5.0) rather than importing one library's type. */
type IconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/** How this person works ΓÇö the block owns the label wording (┬º14d.1), the caller only says which one. */
export type ProfileWorkMode = "remote" | "onsite" | "hybrid"

/** External profile links. Each is optional; an absent one simply drops its meta row. */
export interface ProfileSocialLinks {
    /** GitHub profile URL. */
    github?: string
    /** LinkedIn profile URL. */
    linkedin?: string
    /** Personal site/portfolio URL. */
    website?: string
}

/** One achievement/verification badge earned by this person. */
export interface ProfileBadge {
    /** Stable id ΓÇö used as the chip's React key. */
    id: string
    /** Badge label, already worded by the caller's domain (e.g. "Top mentor"). */
    label: string
    /** Optional leading glyph for the badge chip. */
    icon?: IconComponent
}

/** The person this hero profiles ΓÇö plain data, the block builds the sidebar from it. */
export interface ProfileHeroUser {
    /** Stable id (not rendered; kept for parity with other domain-user shapes). */
    id: string
    /** Full display name. */
    fullName: string
    /** Handle WITHOUT the leading `@` ΓÇö the block adds it (┬º14d.1). */
    handle: string
    /** Role/title line under the name. Row disappears when absent. */
    roleTitle?: string
    /** Short bio/about text. Row disappears when absent. */
    bio?: string
    /** Free-text location (e.g. "Hanoi, Vietnam"). Row disappears when absent. */
    location?: string
    /** How this person works. Row disappears when absent. */
    workMode?: ProfileWorkMode
    /** Photo URL. Empty/missing ΓåÆ `Avatar`'s own fallback chain, never a blank frame. */
    avatarUrl?: string
    /** Leaderboard-style standing (1 = top). Absent ΓåÆ no rank frame/caption at all. */
    rank?: number
    /** Total followers. Absent renders as `0` (a real, known count of nothing). */
    followersCount?: number
    /** Achievement badges earned. Empty/absent ΓåÆ the badges row disappears entirely. */
    badges?: ReadonlyArray<ProfileBadge>
    /** ISO date string this person joined. Required ΓÇö every profile has one. */
    joinedAt: string
    /** External links. Absent/all-empty ΓåÆ the social rows of the meta list disappear. */
    social?: ProfileSocialLinks
}

/** Props for {@link ProfileHero}. */
export interface ProfileHeroProps {
    /** The profiled person. */
    user: ProfileHeroUser
    /** `true` ΓåÆ the viewer IS this person: the primary CTA becomes "Edit profile", follow/hire never show. */
    isSelf?: boolean
    /** `true` (and not `isSelf`) ΓåÆ the primary CTA becomes "Hire me" instead of follow. */
    canHire?: boolean
    /** Whether the viewer already follows this person. Ignored when `isSelf`/`canHire`. */
    following?: boolean
    /** `true` ΓåÆ the follow CTA shows its busy state while the toggle is in flight. */
    isFollowPending?: boolean
    /** Fired when the viewer toggles follow (only reachable when neither `isSelf` nor `canHire`). */
    onToggleFollow?: () => void
    /** Fired when the viewer presses "Hire me" (only reachable when `canHire` and not `isSelf`). See file header, judgement call 3. */
    onHire?: () => void
    /** Fired when the profile owner presses "Edit profile" (only reachable when `isSelf`). */
    onEdit?: () => void
    /** Fired when the share action is pressed. */
    onShare?: () => void
    /** `true` ΓåÆ every real part switches to its own shimmer; the profile stops accepting presses. */
    isSkeleton?: boolean
}

interface PrimaryAction {
    label: string
    variant: ButtonVariant
    prefixIcon: IconComponent
    onPress?: () => void
    isPending?: boolean
}

/** Inputs {@link resolvePrimaryAction} needs to pick the one CTA slot. */
interface ResolvePrimaryActionParams {
    isSelf: boolean
    canHire: boolean
    following: boolean
    isFollowPending: boolean
    onEdit?: () => void
    onHire?: () => void
    onToggleFollow?: () => void
}

const resolvePrimaryAction = (params: ResolvePrimaryActionParams): PrimaryAction => {
    const { isSelf, canHire, following, isFollowPending, onEdit, onHire, onToggleFollow } = params
    if (isSelf) {
        return { label: "Edit profile", variant: "secondary", prefixIcon: PencilSimpleIcon, onPress: onEdit }
    }
    if (canHire) {
        return { label: "Hire me", variant: "primary", prefixIcon: HandshakeIcon, onPress: onHire }
    }
    return {
        label: following ? "Following" : "Follow",
        variant: following ? "secondary" : "primary",
        prefixIcon: following ? UserCheckIcon : UserPlusIcon,
        onPress: onToggleFollow,
        isPending: isFollowPending,
    }
}

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Meta list ΓÇö social links (as text-links) + joined date (plain).
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/** One entry of the social meta list ΓÇö the block's own icon + label per platform. */
interface ProfileSocialMetaEntry {
    key: keyof ProfileSocialLinks
    icon: IconComponent
    label: string
}

/** The block's own label per platform (┬º14d.1) ΓÇö the caller only supplies the URL. */
const SOCIAL_META: ReadonlyArray<ProfileSocialMetaEntry> = [
    { key: "github", icon: GithubLogoIcon, label: "GitHub" },
    { key: "linkedin", icon: LinkedinLogoIcon, label: "LinkedIn" },
    { key: "website", icon: GlobeIcon, label: "Personal site" },
]

/** `Intl`-formatted "Month M, YYYY" from an ISO date string. Empty input ΓåÆ empty string (no bogus date printed). */
const formatJoinedDate = (isoDate: string): string => {
    const date = new Date(isoDate)
    if (Number.isNaN(date.getTime())) return ""
    return new Intl.DateTimeFormat("vi-VN", { month: "long", year: "numeric" }).format(date)
}

/** How this person works, worded by the block (┬º14d.1). */
const WORK_MODE_MAP: Record<ProfileWorkMode, EnumChipEntry> = {
    remote: { label: "Remote" },
    onsite: { label: "Onsite" },
    hybrid: { label: "Hybrid", color: "accent" },
}

/**
 * The bare identity sidebar. See the file header for the reuse contract and the
 * four judgement calls.
 *
 * @param props - {@link ProfileHeroProps}
 */
const ProfileHero = ({
    user,
    isSelf = false,
    canHire = false,
    following = false,
    isFollowPending = false,
    onToggleFollow,
    onHire,
    onEdit,
    onShare,
    isSkeleton = false,
}: ProfileHeroProps) => {
    const { fullName, handle, roleTitle, bio, location, workMode, avatarUrl, rank, followersCount, badges, joinedAt, social } = user

    const action = resolvePrimaryAction({ isSelf, canHire, following, isFollowPending, onEdit, onHire, onToggleFollow })
    const hasBadgesRow = isSkeleton || Boolean(badges && badges.length > 0)
    const hasLocationRow = isSkeleton || Boolean(location) || Boolean(workMode)

    const socialLinks = social ?? {}
    const socialEntries = SOCIAL_META.filter((entry) => Boolean(socialLinks[entry.key]))
    const hasMetaList = isSkeleton || socialEntries.length > 0 || Boolean(joinedAt)

    const nameBlock = (
        <>
            <Typography
                size="h5"
                weight="bold"
                align="center"
                isSkeleton={isSkeleton}
                text={fullName}

            />
            <Typography
                size="sm"
                color="muted"
                align="center"
                isSkeleton={isSkeleton}
                text={isSkeleton ? undefined : `@${handle}`}

            />
            {isSkeleton || roleTitle ? (
                <Typography
                    size="sm"
                    weight="medium"
                    align="center"
                    isSkeleton={isSkeleton}
                    text={roleTitle}

                />
            ) : null}
        </>
    )

    const identitySection = (
        <>
            <ProfileRankAvatar
                name={fullName}
                avatarUrl={avatarUrl}
                rank={rank}
                isSkeleton={isSkeleton}

            />
            <StackV gap={1} principle="name-handle"
                explain="Display name with handle ΓÇö not title-subtitle, because the second line is an identity handle rather than a subtitle."
                align="center" isSkeleton={isSkeleton} items={[() => nameBlock]}  />
        </>
    )

    const statsRow = (
        <>
            <ProfileFollowers followersCount={followersCount} isSkeleton={isSkeleton} />
            {hasBadgesRow ? (
                <ProfileBadges badges={badges} isSkeleton={isSkeleton} />
            ) : null}
        </>
    )

    const actionsRow = (
        <>
            <Button
                classNames={["flex-1"]}
                variant={action.variant}
                label={action.label}
                prefixIcon={action.prefixIcon}
                onPress={action.onPress}
                isPending={action.isPending}
                isSkeleton={isSkeleton}

            />
            <ShareProfileButton onShare={onShare} isSkeleton={isSkeleton} />
        </>
    )

    const metaList = (
        <>
            {(isSkeleton ? SOCIAL_META : socialEntries).map((entry) => {
                const socialRow = (
                    <>
                        <span aria-hidden className="inline-flex shrink-0 text-muted [&_svg]:size-4">
                            <entry.icon />
                        </span>
                        <Typography
                            size="xs"
                            isLink={!isSkeleton}
                            href={isSkeleton ? undefined : socialLinks[entry.key]}
                            isSkeleton={isSkeleton}
                            truncate
                            text={isSkeleton ? undefined : entry.label}

                        />
                    </>
                )
                return <StackH key={entry.key} gap={2} isSkeleton={isSkeleton} items={[() => socialRow]} />
            })}
            <InlineIconLabel
                icon={CalendarBlankIcon}
                tone="default"
                isSkeleton={isSkeleton}
                label={isSkeleton ? undefined : `Joined ${formatJoinedDate(joinedAt)}`}
            />
        </>
    )

    const metaSection = hasMetaList ? (
        <>
            <Divider />
            <StackV gap={4} isSkeleton={isSkeleton} items={[() => metaList]} />
        </>
    ) : null

    const cardBody = (
        <>
            <StackV gap={4} principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                align="center" isSkeleton={isSkeleton} items={[() => identitySection]}  />

            {isSkeleton || bio ? (
                <Typography
                    size="sm"
                    color="muted"
                    align="center"
                    lineClamp={3}
                    isSkeleton={isSkeleton}
                    text={bio}

                />
            ) : null}

            {hasLocationRow ? (
                <Cluster
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    justify="center"
                    items={[
                        ...(isSkeleton || location
                            ? [
                                () => (
                                    <InlineIconLabel
                                        icon={MapPinIcon}
                                        isSkeleton={isSkeleton}
                                        label={location}
                                    />
                                ),
                            ]
                            : []),
                        ...(isSkeleton || workMode
                            ? [
                                () => (
                                    <EnumChip
                                        value={(workMode ?? "remote") as ProfileWorkMode}
                                        map={WORK_MODE_MAP}
                                        isSkeleton={isSkeleton}
                                    />
                                ),
                            ]
                            : []),
                    ]}
                />
            ) : null}

            <StackH gap={3} principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                divider isSkeleton={isSkeleton} items={[() => statsRow]}  />

            <StackH gap={3} isSkeleton={isSkeleton} items={[() => actionsRow]} />

            {metaSection}
        </>
    )

    return (
        <div>
            <SurfaceCard


                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => cardBody]} />}
            />
        </div>
    )
}

export { ProfileHero }

"use client"

import React from "react"
import { LockIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import type { SectionVisibility } from "@/modules/types/entities/user"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { useAppSelector } from "@/redux/hooks"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { EmptyState } from "@/components/composites/feedback/EmptyState"

/** Props for {@link ProfileSectionGuard}. */
export interface ProfileSectionGuardProps {
    /** Which gateable section this tab renders (drives the `sectionVisibility` flag). */
    section: keyof SectionVisibility
    /** The tab's real content, shown when the section is visible to the viewer. */
    children: React.ReactNode
}

/**
 * Wraps a section tab and short-circuits to a graceful "this section is private"
 * {@link EmptyState} when a VISITOR opens a section the owner has hidden
 * (`sectionVisibility[section] === false`). The owner ({@link isSelf}) always sees
 * the real content. Rendering the placeholder here also stops the inner sections
 * from firing their (backend-guarded, doomed) data queries.
 *
 * Fails OPEN: while the profile is still loading, or when the flag is absent, the
 * children render ΓÇö the backend still guards each section's data as the backstop.
 *
 * @param props - {@link ProfileSectionGuardProps}
 */
export const ProfileSectionGuard = ({
    section,
    children,
}: ProfileSectionGuardProps) => {
    const t = useTranslations()
    const username = useProfileUsername()
    const viewer = useAppSelector((state) => state.user.user)
    const { data: user } = useQueryUserProfileSwr(username)

    // "my own profile" ΓÇö mirror PublicProfile's isSelf (username-keyed, id fallback)
    const isSelf = !!viewer && !!user
        && ((!!viewer.username && viewer.username === user.username) || viewer.id === user.id)
    // a visitor on a section the owner switched off ΓåÆ private placeholder
    const isPrivate = !!user && !isSelf && user.sectionVisibility?.[section] === false

    if (isPrivate) {
        return (
            <div className="flex min-w-0 flex-col">
                <EmptyState
                    icon={LockIcon}
                    title={t("publicProfile.sectionPrivate.title")}
                    description={t("publicProfile.sectionPrivate.description")}
                />
            </div>
        )
    }

    return <>{children}</>
}

"use client"

import React, { useCallback, useMemo } from "react"
import { Tabs } from "@heroui/react"
import {
    HouseIcon,
    PuzzlePieceIcon,
    RocketIcon,
    CodeIcon,
    FileTextIcon,
    PulseIcon,
} from "@phosphor-icons/react"
import { useTranslations, useLocale } from "next-intl"
import { usePathname, useRouter } from "next/navigation"
import type { SectionVisibility } from "@/modules/types/entities/user"
import { PROFILE_TABS } from "@/modules/types/entities/profile"
import type { ProfileTab } from "@/modules/types/entities/profile"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"
import { pathConfig } from "@/resources/path"

/**
 * The section tabs gated by `sectionVisibility` (Overview + CV are never gated ΓÇö
 * Overview always shows, CV keeps its own `hasPublicCv` gate).
 */
const SECTION_TABS: ReadonlyArray<keyof SectionVisibility> = [
    "projects",
    "challenges",
    "skills",
    "activity",
]

/** Whether a tab is one of the visibility-gated section tabs. */
const isSectionTab = (tabId: ProfileTab): tabId is keyof SectionVisibility =>
    (SECTION_TABS as ReadonlyArray<ProfileTab>).includes(tabId)

/** Leading icon shown on each profile tab, keyed by tab id. */
const TAB_ICONS: Record<ProfileTab, typeof HouseIcon> = {
    overview: HouseIcon,
    challenges: PuzzlePieceIcon,
    projects: RocketIcon,
    skills: CodeIcon,
    cv: FileTextIcon,
    activity: PulseIcon,
}

/** Props for {@link ProfileTabsBar}. */
export interface ProfileTabsBarProps {
    /** The viewed user's canonical username (drives every tab's href). */
    username: string
    /** Whether the viewer is the profile owner ΓÇö shows the "CV" tab even without a public CV. */
    isSelf: boolean
    /** Whether the viewed user has a PUBLIC CV ΓÇö shows the "CV" tab to visitors too. */
    hasPublicCv: boolean
    /**
     * The viewed user's per-section visibility (all default true). A section tab is
     * withheld from VISITORS when its flag is false; the owner ({@link isSelf}) always
     * sees every tab (with a "┬╖ hidden" marker on hidden ones). Absent = all visible.
     */
    sectionVisibility?: SectionVisibility
}

/**
 * Build the href for a profile tab. Every tab nests under `/profile/<username>`,
 * INCLUDING "cv" ΓÇö the public, read-only CV view (`/profile/<username>/cv`). The
 * owner's private editor stays reachable from the "Edit CV" button inside
 * that view (the always-own `/profile/cv` gallery).
 */
const tabHref = (locale: string, username: string, tabId: ProfileTab): string => {
    const profile = pathConfig().locale(locale).profile(username)
    switch (tabId) {
    case "overview":
        return profile.overview().build()
    case "projects":
        return profile.projects().build()
    case "challenges":
        return profile.challenges().build()
    case "skills":
        return profile.skills().build()
    case "activity":
        return profile.activity().build()
    case "cv":
        return profile.cv().build()
    }
}

/**
 * Full-width tab strip for the profile page. The page registers it as the global
 * Navbar's bottom layer ({@link useRegisterNavbarBottomLayer}); the Navbar renders
 * it flush under its primary row and owns the single bottom border + sticky, so
 * this strip carries no border / sticky / bg of its own. Uses the native HeroUI
 * secondary Tabs (foreground text on the selected tab + an accent underline
 * indicator).
 *
 * Each tab is a real nested route (`/profile/<username>/<tab>`, bare = overview) ΓÇö
 * the active tab is derived from the URL pathname and switching a tab
 * `router.push`es its href, mirroring the `pathname === href` + `router.push`
 * pattern `SettingsLayout` already uses for its own route-derived nav. No store,
 * no `?tab=` query param: the URL alone is the source of truth, so the open tab
 * is shareable / bookmarkable / back-forward friendly for free.
 *
 * @param props - {@link ProfileTabsBarProps}
 */
export const ProfileTabsBar = ({ username, isSelf, hasPublicCv, sectionVisibility}: ProfileTabsBarProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()
    // Whether a SECTION tab is hidden for the current viewer: false flag + visitor.
    // The owner (isSelf) always sees it (just marked "┬╖ hidden"); an absent flag = visible.
    const isSectionHidden = useCallback(
        (tabId: ProfileTab): boolean =>
            !isSelf && isSectionTab(tabId) && sectionVisibility?.[tabId] === false,
        [isSelf, sectionVisibility],
    )
    // Tab gating, combined:
    //  ΓÇó "cv" shows for the owner (always) or when the viewed user has a PUBLIC CV.
    //  ΓÇó a section tab (projects/challenges/skills/activity) is withheld from VISITORS
    //    when its sectionVisibility flag is false. Overview is never gated.
    const visibleTabs = useMemo(
        () => PROFILE_TABS.filter((tabId) => {
            if (tabId === "cv") {
                return isSelf || hasPublicCv
            }
            return !isSectionHidden(tabId)
        }),
        [isSelf, hasPublicCv, isSectionHidden],
    )

    // active tab = the tab whose path is a PREFIX of the current pathname (so a
    // nested sub-route like `/challenges/<courseId>/<id>` still lights up its tab).
    // "overview" is the bare `/profile/<username>` path ΓÇö a prefix of everything ΓÇö
    // so it's only the FALLBACK when no deeper tab matches.
    const activeTab = useMemo<ProfileTab>(() => {
        const match = visibleTabs
            .filter((tabId) => tabId !== "overview")
            .find((tabId) => {
                const href = tabHref(locale, username, tabId)
                return pathname === href || pathname.startsWith(`${href}/`)
            })
        return match ?? "overview"
    }, [visibleTabs, pathname, locale, username])

    return (
        // Rendered as the Navbar's bottom layer ΓÇö no border / sticky / bg of its
        // own; the Navbar root owns the single bottom border and the sticky.
        <div className={"w-full"}>
            <div className="w-full px-6">
                <ExtendedTabs
                    selectedKey={activeTab}
                    onSelectionChange={(key) => router.push(tabHref(locale, username, key as ProfileTab))}
                >
                    <Tabs.ListContainer>
                        <Tabs.List aria-label={t("publicProfile.title")}>
                            {visibleTabs.map((tabId) => {
                                const TabIcon = TAB_ICONS[tabId]
                                return (
                                    <Tabs.Tab
                                        key={tabId}
                                        id={tabId}
                                        aria-controls={`profile-panel-${tabId}`}
                                    >
                                        <span className="flex items-center gap-2">
                                            <TabIcon
                                                aria-hidden
                                                focusable="false"
                                                className="size-5 shrink-0"
                                            />
                                            {/* mobile = icon only; label shows from md up */}
                                            <span className="hidden @app-md:inline">
                                                {t(`publicProfile.tabs.${tabId}`)}
                                                {/* owner-only marker on a section hidden from
                                                    visitors (visitors never see the tab at all) */}
                                                {isSelf && isSectionTab(tabId) && sectionVisibility?.[tabId] === false ? (
                                                    <span className="ml-1 text-foreground-500">
                                                        {t("publicProfile.tabHidden")}
                                                    </span>
                                                ) : null}
                                            </span>
                                        </span>
                                        <Tabs.Indicator />
                                    </Tabs.Tab>
                                )
                            })}
                        </Tabs.List>
                    </Tabs.ListContainer>
                </ExtendedTabs>
            </div>
        </div>
    )
}

"use client"

import React from "react"
/** Props for {@link RankBadge}. */
export interface RankBadgeProps {
    /** Display label for the rank (already localised, e.g. "Senior"). */
    label: string
    /** Hex colour encoding the rank tier (grey ΓåÆ bronze ΓåÆ silver ΓåÆ gold). */
    color: string
}

/**
 * Seniority rank pill ΓÇö a coloured dot + the rank label (Beginner ΓåÆ Senior),
 * tinted by the rank's tier colour. Presentational: the caller resolves the
 * user's rank ΓåÆ `{ label, color }` (e.g. via `getRank`) and passes it in.
 *
 * NO border: a soft 10%-tint fill of the rank colour with the dot + label in the
 * full colour (a chip is one colour family, not an outline). `color` is a runtime
 * hex, so the fill uses `color-mix(... 10%, transparent)` (format-agnostic) ΓÇö the
 * inline-style equivalent of `bg-[color]/10`.
 *
 * @param props - {@link RankBadgeProps}
 */
export const RankBadge = ({
    label,
    color}: RankBadgeProps) => {
    return (
        <span
            className={"inline-flex w-fit items-center gap-2 rounded-full px-2 py-0 text-xs font-medium"}
            style={{
                backgroundColor: `color-mix(in srgb, ${color} 10%, transparent)`,
                color,
            }}
        >
            <span
                className="size-2 rounded-full"
                style={{
                    backgroundColor: color,
                }}
            />
            {label}
        </span>
    )
}

"use client"

import React from "react"
import {
    CaretUpIcon,
    CaretDownIcon,
} from "@phosphor-icons/react"
import {
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** Props for {@link RankDeltaCaret}. */
export interface RankDeltaCaretProps extends WithClassNames<undefined> {
    /**
     * Rank movement vs the previous period (`lastRank - currentRank`): positive
     * = climbed N places (Γû▓ green), negative = dropped (Γû╝ red), 0 = unchanged
     * (muted dash), null = no baseline (renders nothing).
     */
    delta: number | null
}

/**
 * The rank-movement caret shown at the end of a leaderboard row: a green up
 * arrow + count when the user climbed, a red down arrow + count when they
 * dropped, a muted dash when unchanged, and nothing when there's no baseline.
 * Reused by the weekly-league board + the global leaderboard.
 *
 * @param props - {@link RankDeltaCaretProps}
 */
export const RankDeltaCaret = ({
    delta,
    className,
}: RankDeltaCaretProps) => {
    // no last-period baseline ΓåÆ an EMPTY SPACER that still reserves the column width
    // (the caller's `className` carries the `w-8`), so a #1 row with no movement keeps
    // the value/delta columns aligned with the rows below it instead of letting the
    // value slide right into the empty slot (the teacher, 2026-07-17: "the green ones need to line up").
    if (delta === null) {
        return <span className={cn(className)} aria-hidden />
    }
    // unchanged ΓåÆ a muted dash so the column still aligns
    if (delta === 0) {
        return (
            <span className={cn("text-xs text-muted", className)}>
                ΓÇö
            </span>
        )
    }
    const climbed = delta > 0
    return (
        <span
            className={cn(
                "flex items-center gap-0 text-xs font-medium",
                climbed ? "text-success-soft-foreground" : "text-danger-soft-foreground",
                className,
            )}
        >
            {climbed ? (
                <CaretUpIcon className="size-3.5" />
            ) : (
                <CaretDownIcon className="size-3.5" />
            )}
            {Math.abs(delta)}
        </span>
    )
}
